import { requireProjectAccess, apiUser, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { projectId } from '@/lib/projects';
import { ensureReviewTables, persistReviewBatch } from '@/lib/review-report';
import { availableReviewDates, reviewByDate } from '@/lib/review-seed';
import { logAction } from '@/lib/ops';

export const dynamic = 'force-dynamic';

export async function GET(request: Request) {
  const url = new URL(request.url);
  const rawProject = url.searchParams.get('projectId');
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, rawProject, 'read')
    : (await apiUser() ? { ok: true, status: 200, error: '', context: { projectId: String(rawProject || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;

  await ensureSchema();
  const d1 = db();
  await ensureReviewTables(d1);
  const page = Math.max(1, parseInt(url.searchParams.get('page') || '1', 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(url.searchParams.get('pageSize') || '20', 10)));
  const offset = (page - 1) * pageSize;

  const source = (url.searchParams.get('source') || 'all').trim();
  const status = (url.searchParams.get('status') || 'pending').trim();
  const action = (url.searchParams.get('action') || '').trim();
  const sentiment = (url.searchParams.get('sentiment') || '').trim();
  const category = (url.searchParams.get('category') || '').trim();
  const date = (url.searchParams.get('date') || '').trim();
  const query = (url.searchParams.get('query') || '').trim();

  const availableDates = await availableReviewDates(project).catch(() => [] as string[]);

  // If date is requested and no review batch exists yet, idempotent ensure batch exists
  if (date) {
    const existing = await d1.prepare('SELECT id FROM note_review_batches WHERE project_id=? AND date_key=? LIMIT 1').bind(project, date).first<{ id: string }>();
    if (!existing) {
      return Response.json({
        ok: true,
        items: [],
        total: 0,
        page,
        pageSize,
        summary: {
          totalPending: 0,
          replyPending: 0,
          deletePending: 0,
          supplementPending: 0,
          observePending: 0,
          handledCount: 0,
        },
        availableDates,
        needsRecalculation: true,
      });
    }
  }

  // Resolve target review date: either explicit user selection, or latest active batch
  const latestBatch = await d1.prepare('SELECT date_key FROM note_review_batches WHERE project_id=? ORDER BY date_key DESC LIMIT 1').bind(project).first<{ date_key: string }>();
  const effectiveReviewDate = date || (latestBatch ? latestBatch.date_key : null);

  // Overall KPI summary counts directly from DB
  const [kcSummary, raSummary] = await Promise.all([
    d1.prepare(`
      SELECT 
        COUNT(*) AS total,
        SUM(CASE WHEN action LIKE '%回复%' AND treatment_status != '已处理' THEN 1 ELSE 0 END) AS replyPending,
        SUM(CASE WHEN action LIKE '%删%' AND treatment_status != '已处理' THEN 1 ELSE 0 END) AS deletePending,
        SUM(CASE WHEN action LIKE '%补%' AND treatment_status != '已处理' THEN 1 ELSE 0 END) AS supplementPending,
        SUM(CASE WHEN action NOT LIKE '%回复%' AND action NOT LIKE '%删%' AND action NOT LIKE '%补%' AND treatment_status != '已处理' THEN 1 ELSE 0 END) AS observePending,
        SUM(CASE WHEN treatment_status = '已处理' THEN 1 ELSE 0 END) AS handledCount
      FROM key_comments
      WHERE project_id = ? AND disappeared_at IS NULL
    `).bind(project).first<{
      total: number; replyPending: number; deletePending: number; supplementPending: number; observePending: number; handledCount: number;
    }>(),
    d1.prepare(`
      SELECT 
        COUNT(*) AS total,
        SUM(CASE WHEN (action = 'needReply' OR action LIKE '%回复%') AND status != '已处理' THEN 1 ELSE 0 END) AS replyPending,
        SUM(CASE WHEN (action = 'needDelete' OR action LIKE '%删%') AND status != '已处理' THEN 1 ELSE 0 END) AS deletePending,
        SUM(CASE WHEN (action = 'needSupplement' OR action LIKE '%补%') AND status != '已处理' THEN 1 ELSE 0 END) AS supplementPending,
        SUM(CASE WHEN status = '已处理' THEN 1 ELSE 0 END) AS handledCount
      FROM review_action_items
      WHERE project_id = ? AND active = 1 AND (? = '' OR date_key = ?)
    `).bind(project, effectiveReviewDate || '', effectiveReviewDate || '').first<{
      total: number; replyPending: number; deletePending: number; supplementPending: number; handledCount: number;
    }>(),
  ]);

  const replyPending = Number(kcSummary?.replyPending || 0) + Number(raSummary?.replyPending || 0);
  const deletePending = Number(kcSummary?.deletePending || 0) + Number(raSummary?.deletePending || 0);
  const supplementPending = Number(kcSummary?.supplementPending || 0) + Number(raSummary?.supplementPending || 0);
  const observePending = Number(kcSummary?.observePending || 0);
  const handledCount = Number(kcSummary?.handledCount || 0) + Number(raSummary?.handledCount || 0);
  const totalPending = replyPending + deletePending + supplementPending + observePending;

  // Unified CTE for filtered rows
  const dateParam = date || '';
  const whereClauses: string[] = ['1=1'];
  const filterParams: unknown[] = [project, project];

  if (source === 'key-comment') {
    whereClauses.push("source = 'key-comment'");
  } else if (source === 'review-batch') {
    whereClauses.push("source = 'review-batch'");
  }

  if (status === 'pending') {
    whereClauses.push("status = 'pending'");
  } else if (status === 'handled') {
    whereClauses.push("status = 'handled'");
  }

  if (action) {
    whereClauses.push('action = ?');
    filterParams.push(action);
  }

  if (sentiment) {
    whereClauses.push('sentiment = ?');
    filterParams.push(sentiment);
  }

  if (category) {
    whereClauses.push('category = ?');
    filterParams.push(category);
  }

  if (dateParam) {
    whereClauses.push('(batchDate = ? OR batchDate IS NULL)');
    filterParams.push(dateParam);
  }

  if (query) {
    whereClauses.push('(content LIKE ? OR author LIKE ? OR noteId LIKE ? OR reason LIKE ? OR title LIKE ?)');
    const q = '%' + query + '%';
    filterParams.push(q, q, q, q, q);
  }

  const filterSql = ' WHERE ' + whereClauses.join(' AND ');

  const cteSql = `
    WITH unified AS (
      SELECT 
        'key-comment' AS source,
        kc.id AS rawId,
        'kc-' || kc.id AS id,
        'comment' AS itemType,
        kc.note_id AS noteId,
        kc.author AS author,
        kc.content AS content,
        kc.sentiment AS sentiment,
        kc.category AS category,
        CASE 
          WHEN kc.action LIKE '%回复%' THEN 'reply'
          WHEN kc.action LIKE '%删%' THEN 'delete'
          WHEN kc.action LIKE '%补%' THEN 'supplement'
          ELSE 'observe'
        END AS action,
        CASE WHEN kc.treatment_status = '已处理' THEN 'handled' ELSE 'pending' END AS status,
        kc.treatment_status AS rawStatus,
        kc.treatment_method AS treatmentMethod,
        kc.last_seen_at AS time,
        kc.sentiment || ' · ' || kc.category || ' · ' || kc.action AS reason,
        COALESCE(n.title, '') AS title,
        COALESCE(n.url, '') AS link,
        NULL AS batchDate
      FROM key_comments kc
      LEFT JOIN notes n ON n.id = kc.note_id
      WHERE kc.project_id = ? AND kc.disappeared_at IS NULL

      UNION ALL

      SELECT 
        'review-batch' AS source,
        CAST(ra.id AS TEXT) AS rawId,
        'rb-' || ra.id AS id,
        'note' AS itemType,
        ra.link AS noteId,
        ra.blogger AS author,
        ra.sample_json AS content,
        '' AS sentiment,
        '' AS category,
        CASE 
          WHEN ra.action = 'needReply' OR ra.action LIKE '%回复%' THEN 'reply'
          WHEN ra.action = 'needDelete' OR ra.action LIKE '%删%' THEN 'delete'
          WHEN ra.action = 'needSupplement' OR ra.action LIKE '%补%' THEN 'supplement'
          ELSE 'observe'
        END AS action,
        CASE WHEN ra.status = '已处理' THEN 'handled' ELSE 'pending' END AS status,
        ra.status AS rawStatus,
        '' AS treatmentMethod,
        ra.created_at AS time,
        ra.reason AS reason,
        ra.blogger AS title,
        ra.link AS link,
        ra.date_key AS batchDate
      FROM review_action_items ra
      WHERE ra.project_id = ? AND ra.active = 1 AND (? = '' OR ra.date_key = ?)
    )
  `;

  const [countRes, rowsRes] = await Promise.all([
    d1.prepare(cteSql + ' SELECT COUNT(*) AS total FROM unified' + filterSql).bind(project, project, effectiveReviewDate || '', effectiveReviewDate || '', ...filterParams.slice(2)).first<{ total: number }>(),
    d1.prepare(cteSql + ' SELECT * FROM unified' + filterSql + ' ORDER BY time DESC, id DESC LIMIT ? OFFSET ?')
      .bind(project, project, effectiveReviewDate || '', effectiveReviewDate || '', ...filterParams.slice(2), pageSize, offset).all<{
        source: 'key-comment' | 'review-batch';
        rawId: string;
        id: string;
        itemType: 'comment' | 'note';
        noteId: string;
        author: string;
        content: string;
        sentiment: string;
        category: string;
        action: 'reply' | 'delete' | 'supplement' | 'observe';
        status: 'pending' | 'handled';
        rawStatus: string;
        treatmentMethod: string;
        time: string;
        reason: string;
        title: string;
        link: string;
        batchDate: string | null;
      }>(),
  ]);

  const total = Number(countRes?.total || 0);
  const items = (rowsRes.results || []).map((row) => {
    let displayContent = row.content;
    if (row.source === 'review-batch') {
      try {
        const arr = JSON.parse(row.content || '[]');
        if (Array.isArray(arr) && arr.length > 0) {
          displayContent = arr.map((s) => String((s as { t?: string }).t || s || '')).filter(Boolean).join('；') || '判定需处理笔记';
        } else {
          displayContent = '判定需处理笔记';
        }
      } catch {
        displayContent = '判定需处理笔记';
      }
    }
    return {
      id: row.id,
      rawId: row.rawId,
      source: row.source,
      itemType: row.itemType,
      noteId: row.noteId,
      author: row.author,
      content: displayContent,
      sentiment: row.sentiment,
      category: row.category,
      action: row.action,
      status: row.status,
      treatmentMethod: row.treatmentMethod,
      time: row.time,
      reason: row.reason,
      title: row.title,
      link: row.link,
      batchDate: row.batchDate,
    };
  });

  return Response.json({
    ok: true,
    items,
    total,
    page,
    pageSize,
    summary: {
      totalPending,
      replyPending,
      deletePending,
      supplementPending,
      observePending,
      handledCount,
    },
    availableDates,
  });
}

export async function POST(request: Request) {
  let body: {
    id?: string;
    rawId?: string;
    source?: 'key-comment' | 'review-batch';
    action?: 'resolve' | 'delete' | 'recalculate';
    method?: string;
    projectId?: string;
    date?: string;
  } = {};
  try { body = await request.json() as typeof body; } catch { return jsonError('无效的请求体'); }
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, body.projectId, 'write')
    : (await apiUser(true) ? { ok: true, status: 200, error: '', context: { projectId: String(body.projectId || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;

  await ensureSchema();
  const d1 = db();
  await ensureReviewTables(d1);
  try {

    if (body.action === 'recalculate') {
      const dateKey = (body.date || '').trim();
      if (!dateKey) return jsonError('缺少日期参数', 400);
      const result = await reviewByDate(project, dateKey).catch(() => null);
      if (!result) return jsonError(dateKey + '暂无规则判定数据', 404);
      const batchId = await persistReviewBatch(d1, project, result);
      await logAction('重算规则判定批次', 'review_batch', batchId, `重算 ${dateKey} 批次待办`, project);
      return Response.json({ ok: true, batchId });
    }

    const source = body.source || (body.id?.startsWith('rb-') ? 'review-batch' : 'key-comment');
    const rawId = body.rawId || body.id?.replace(/^(kc-|rb-)/, '');
    if (!rawId) return jsonError('缺少项目 ID', 400);

    if (body.action === 'resolve') {
      const method = body.method || '已人工核实处置';
      const now = new Date().toISOString();
      if (source === 'key-comment') {
        await d1.prepare('UPDATE key_comments SET treatment_status = ?, treatment_method = ? WHERE id = ? AND project_id = ?')
          .bind('已处理', method, rawId, project).run();
      } else {
        await d1.prepare("UPDATE review_action_items SET status = '已处理', handled_at = ?, treatment_method = ? WHERE id = ? AND project_id = ?")
          .bind(now, method, Number(rawId), project).run();
      }
      await logAction('处置待办', source, rawId, `标记已处理：${method}`, project);
      return Response.json({ ok: true });
    }

    if (body.action === 'delete') {
      if (source === 'key-comment') {
        await d1.prepare('DELETE FROM key_comments WHERE id = ? AND project_id = ?').bind(rawId, project).run();
      } else {
        await d1.prepare('DELETE FROM review_action_items WHERE id = ? AND project_id = ?').bind(Number(rawId), project).run();
      }
      await logAction('删除待办', source, rawId, '移除待办项', project);
      return Response.json({ ok: true });
    }

    return jsonError('未知操作类型', 400);
  } catch (err) {
    return jsonError(err instanceof Error ? err.message : '操作失败', 500);
  }
}

import { runtimeVars, warmWorkerEnv } from '@/lib/runtime-env';
void warmWorkerEnv();
import { requireProjectAccess, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { projectId } from '@/lib/projects';
import { buildQueryPlan, reportHtml, type MetricDefinition, type ReportSpec } from '@/lib/report-agent';
import { cacheNoteCovers } from '@/lib/note-covers';
import { fetchIpScgTasks, fetchIpScgNotes } from '@/lib/data-fetchers';
import { getLingxiTrackData, type LingxiTrackResult } from '@/lib/lingxi';
import { parseDateKey } from '@/lib/comment-review';
import { reviewByDate } from '@/lib/review-seed';
import { buildReviewInsight, ensureReviewTables, persistReviewBatch, reviewSections, reviewSummary } from '@/lib/review-report';

export const dynamic = 'force-dynamic';
const text = (v: unknown) => String(v ?? '').trim();
const number = (v: unknown) => Number(v || 0);
const runtime = () => runtimeVars();

export async function GET(request: Request) {
  const url = new URL(request.url);
  const access = await requireProjectAccess(request, url.searchParams.get('projectId'), 'read');
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  await ensureSchema();
  const id = url.searchParams.get('id');
  const type = url.searchParams.get('type');

  if (id && type === 'report') {
    const row = await db().prepare(`SELECT id,run_id AS runId,title,period_start AS periodStart,period_end AS periodEnd,status,report_spec_json AS reportSpecJson,html,source_manifest_json AS sourceManifestJson,created_at AS createdAt FROM report_versions WHERE id=? AND project_id=?`).bind(id, project).first();
    return row ? Response.json({ ok: true, report: row }) : jsonError('报告不存在', 404);
  }
  if (id) {
    const [run, steps] = await Promise.all([
      db().prepare(`SELECT id,prompt,status,engine,date_start AS dateStart,date_end AS dateEnd,query_plan_json AS queryPlanJson,report_spec_json AS reportSpecJson,progress,error,created_at AS createdAt,finished_at AS finishedAt FROM agent_runs WHERE id=? AND project_id=?`).bind(id, project).first(),
      db().prepare(`SELECT id,step_order AS stepOrder,name,status,detail,started_at AS startedAt,finished_at AS finishedAt FROM agent_steps WHERE run_id=? ORDER BY step_order`).bind(id).all(),
    ]);
    return run ? Response.json({ ok: true, run, steps: steps.results }) : jsonError('任务不存在', 404);
  }
  const [runs, reports] = await Promise.all([
    db().prepare(`SELECT id,prompt,status,engine,date_start AS dateStart,date_end AS dateEnd,progress,error,created_at AS createdAt,finished_at AS finishedAt FROM agent_runs WHERE project_id=? ORDER BY created_at DESC LIMIT 20`).bind(project).all(),
    db().prepare(`SELECT id,run_id AS runId,title,period_start AS periodStart,period_end AS periodEnd,status,created_at AS createdAt FROM report_versions WHERE project_id=? ORDER BY created_at DESC LIMIT 20`).bind(project).all(),
  ]);
  return Response.json({ ok: true, runs: runs.results, reports: reports.results });
}

async function projectFacts(project: string, start: string, end: string) {
  const d1 = db();
  const endExclusive = `${end}T23:59:59`;
  const [projectRow, counts, pipelines, trend, topics, notes, sources, supplier] = await Promise.all([
    d1.prepare(`SELECT name,spu,brand,category FROM projects WHERE id=?`).bind(project).first<{ name: string; spu: string; brand: string; category: string }>(),
    d1.prepare(`SELECT COUNT(DISTINCT pn.note_id) AS notes,COALESCE(SUM(pn.comment_total),0) AS comments,COALESCE(SUM(pn.positive_count),0) AS positive,COALESCE(SUM(pn.negative_count),0) AS negative,COALESCE(SUM(pn.question_count),0) AS questions,COALESCE(SUM(np.exposure),0) AS exposure,COALESCE(SUM(np.read_count),0) AS reads,COALESCE(SUM(np.interaction_count),0) AS interactions,COALESCE(SUM(np.note_price),0) AS cost FROM project_notes pn LEFT JOIN notes n ON n.id=pn.note_id LEFT JOIN note_profiles np ON np.note_id=pn.note_id WHERE pn.project_id=? AND (n.published_at IS NULL OR (n.published_at>=? AND n.published_at<=?))`).bind(project, start, endExclusive).first<Record<string, number>>(),
    d1.prepare(`SELECT name,target_count AS targetCount,delivered_count AS deliveredCount,budget,spent FROM project_pipelines WHERE project_id=? ORDER BY name`).bind(project).all<Record<string, string | number>>(),
    d1.prepare(`SELECT substr(captured_at,1,10) AS date,SUM(total_count) AS comments,SUM(positive_count) AS positive,SUM(negative_count) AS negative,SUM(question_count) AS questions FROM comment_snapshots WHERE project_id=? AND captured_at>=? AND captured_at<=? GROUP BY substr(captured_at,1,10) ORDER BY date`).bind(project, start, endExclusive).all<Record<string, string | number>>(),
    d1.prepare(`SELECT category AS topic,COUNT(*) AS count,SUM(CASE WHEN sentiment='负向' THEN 1 ELSE 0 END) AS negative,SUM(CASE WHEN treatment_status='已处理' THEN 1 ELSE 0 END) AS handled FROM key_comments WHERE project_id=? AND last_seen_at>=? AND last_seen_at<=? GROUP BY category ORDER BY count DESC LIMIT 10`).bind(project, start, endExclusive).all<Record<string, string | number>>(),
    d1.prepare(`SELECT pn.note_id AS noteId,COALESCE(n.title,pn.note_id) AS title,COALESCE(n.author,'') AS author,pn.status,pn.comment_total AS comments,pn.positive_count AS positive,pn.negative_count AS negative,COALESCE(np.read_count,0) AS reads,COALESCE(np.interaction_count,0) AS interactions,COALESCE(np.category1,'待分类') AS category,COALESCE(np.cover_url,'') AS coverUrl,COALESCE(n.url,'') AS noteUrl FROM project_notes pn LEFT JOIN notes n ON n.id=pn.note_id LEFT JOIN note_profiles np ON np.note_id=pn.note_id WHERE pn.project_id=? ORDER BY np.interaction_count DESC,pn.comment_total DESC LIMIT 12`).bind(project).all<Record<string, string | number>>(),
    d1.prepare(`SELECT name,type,status,COALESCE(last_synced_at,'尚未同步') AS freshness,last_row_count AS rows FROM data_sources WHERE project_id=? ORDER BY updated_at DESC`).bind(project).all<Record<string, string | number>>(),
    d1.prepare(`SELECT COUNT(*) AS total,SUM(CASE WHEN visibility IN ('原文一致','有修改') THEN 1 ELSE 0 END) AS visible FROM supplier_comments WHERE project_id=?`).bind(project).first<{ total: number; visible: number }>(),
  ]);
  return { project: projectRow || { name: '项目', spu: '', brand: '', category: '' }, counts: counts || {}, pipelines: pipelines.results || [], trend: trend.results || [], topics: topics.results || [], notes: notes.results || [], sources: sources.results || [], supplier: supplier || { total: 0, visible: 0 } };
}

type ExternalFactsResult = {
  paidAds?: { totals: Record<string, number>; accounts: Array<Record<string, unknown>> };
  lingxi?: LingxiTrackResult;
  ipscg?: { task: string; total: number; topNotes: Array<Record<string, unknown>> };
  warnings: string[];
};

async function externalFacts(project: string, prompt: string, start: string, end: string): Promise<ExternalFactsResult> {
  const d1 = db();
  const result: {
    paidAds?: { totals: Record<string, number>; accounts: Array<Record<string, unknown>> };
    lingxi?: LingxiTrackResult;
    ipscg?: { task: string; total: number; topNotes: Array<Record<string, unknown>> };
    warnings: string[];
  } = { warnings: [] };

  if (/投放|聚光|消耗|花费|CTR|点击|账户/.test(prompt) || /经营|复盘|日报|看板/.test(prompt)) {
    try {
      const totals = await d1.prepare(`SELECT COUNT(*) AS accounts, COALESCE(SUM(spend),0) AS spend, COALESCE(SUM(impressions),0) AS impressions,
        COALESCE(SUM(clicks),0) AS clicks, COALESCE(SUM(interactions),0) AS interactions,
        CASE WHEN SUM(impressions)>0 THEN SUM(clicks)*1.0/SUM(impressions) ELSE 0 END AS ctr
        FROM paid_ad_metrics WHERE project_id=?`).bind(project).first<Record<string, number>>();
      const accounts = await d1.prepare(`SELECT account_name AS account, brand_name AS brand, metric_date AS metricDate, spend, impressions, clicks, ctr, interactions, balance
        FROM paid_ad_metrics WHERE project_id=? ORDER BY spend DESC LIMIT 20`).bind(project).all();

      if (totals && Number(totals.accounts) > 0) {
        result.paidAds = { totals, accounts: accounts.results || [] };
      }
    } catch {
      result.warnings.push('聚光投放数据读取异常。');
    }
  }

  if (/灵犀|母婴|大盘|赛道|机会|供需|潜力|排行|Top30|竞品|行业|经营|看板|复盘|趋势/.test(prompt)) {
    try {
      const lingxiData = getLingxiTrackData(start, end, '母婴出行');
      result.lingxi = lingxiData;
    } catch {
      result.warnings.push('灵犀大盘数据直连接口异常。');
    }
  }

  if (/竞品|UGC|抓取|关键词|笔记样本|声量/.test(prompt)) {
    try {
      const tasks = await fetchIpScgTasks();
      const picked = tasks.filter(t => prompt.includes(t.taskName) || /竞品|UGC|声量/.test(prompt) && /竞品|a2|爱他美|合生元|金领冠/i.test(t.taskName)).slice(0, 2);
      const chosen = picked.length ? picked : tasks.filter(t => /启萃|飞鹤/.test(t.taskName)).slice(0, 1);
      if (chosen.length) {
        const task = chosen[0];
        const notes = await fetchIpScgNotes(task.taskId, 30);
        const sorted = notes.sort((a, b) => (b.likedCount + b.collectedCount + b.commentCount) - (a.likedCount + a.collectedCount + a.commentCount));
        result.ipscg = { task: task.taskName, total: notes.length, topNotes: sorted.slice(0, 10).map(n => ({ 笔记ID: n.noteId, 关键词: n.keyword, 标题: n.title, 博主: n.nickname, 发布时间: n.pubTime, 点赞: n.likedCount, 收藏: n.collectedCount, 评论: n.commentCount, 链接: n.noteUrl })) };
      }
    } catch {
      result.warnings.push('IPSCG 素材系统不可达，已跳过外部笔记样本。');
    }
  }

  return result;
}

async function aiSummary(prompt: string, spec: ReportSpec) {
  const r = runtime();
  const key = r.KEYSTONE_API_KEY || process.env.KEYSTONE_API_KEY;
  const model = r.KEYSTONE_MODEL || process.env.KEYSTONE_MODEL;
  const rawBase = r.KEYSTONE_BASE_URL || process.env.KEYSTONE_BASE_URL || 'https://keystonehk.ai/v1'; const base = rawBase.endsWith('/') ? rawBase.slice(0, -1) : rawBase;
  if (!key || !model) return null;
  const response = await fetch(`${base}/chat/completions`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      max_tokens: 900,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: '你是社媒与电商经营分析助手。只返回 JSON：{"summary":[4条简洁中文结论]}。涵盖项目内容表现、聚光投放消耗与灵犀母婴大盘机会。不得编造输入中没有的数据。' },
        { role: 'user', content: JSON.stringify({ request: prompt, kpis: spec.kpis, sections: spec.sections.slice(0, 6) }) }
      ]
    })
  });
  if (!response.ok) return null;
  const payload = await response.json() as { choices?: Array<{ message?: { content?: string } }> };
  const content = payload.choices?.[0]?.message?.content;
  if (!content) return null;
  try {
    const parsed = JSON.parse(content) as { summary?: unknown };
    return Array.isArray(parsed.summary) ? parsed.summary.map(String).slice(0, 6) : null;
  } catch {
    return null;
  }
}

async function aiReviewInsight(prompt: string, result: { counts: Record<string, number>; dateKey: string; noteCount: number; reportable: Array<{ blogger: string; positive: number; mentionRate: number }>; basic: Array<{ blogger: string; positive: number; mentionRate: number }>; needSupplement: Array<{ blogger: string; positive: number; supplementNeed: number }>; needReply: Array<{ blogger: string; replyHits: string[] }>; needDelete: Array<{ blogger: string; deleteHits: string[] }> }): Promise<string[]> {
  const fallback = buildReviewInsight(result as never);
  try {
    const r = runtime();
    const key = r.KEYSTONE_API_KEY || process.env.KEYSTONE_API_KEY;
    const model = r.KEYSTONE_MODEL || process.env.KEYSTONE_MODEL;
    const rawBase = r.KEYSTONE_BASE_URL || process.env.KEYSTONE_BASE_URL || 'https://keystonehk.ai/v1';
    if (!key || !model) return fallback;
    const base = rawBase.endsWith('/') ? rawBase.slice(0, -1) : rawBase;
    const top = (list: Array<Record<string, unknown>>) => list.slice(0, 8);
    const response = await fetch(base + '/chat/completions', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model, temperature: 0.2, max_tokens: 700, response_format: { type: 'json_object' }, messages: [
        { role: 'system', content: '你是母婴社媒评论验收顾问。只返回 JSON：{"insights":[不超过7条简洁中文]}。基于给定判定数据给出结论、补量优先级与处置建议，不得编造数据中没有的笔记或数字。' },
        { role: 'user', content: JSON.stringify({ request: prompt, date: result.dateKey, counts: result.counts, reportable: top(result.reportable as never), basic: top(result.basic as never), supplementGap: top(result.needSupplement as never), replySample: top(result.needReply as never), deleteSample: top(result.needDelete as never) }) }] }) });
    if (!response.ok) return fallback;
    const payload = await response.json() as { choices?: Array<{ message?: { content?: string } }> };
    const content = payload.choices?.[0]?.message?.content;
    if (!content) return fallback;
    const parsed = JSON.parse(content) as { insights?: unknown };
    return Array.isArray(parsed.insights) && parsed.insights.length ? parsed.insights.map(String).slice(0, 7) : fallback;
  } catch { return fallback; }
}
