  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  try {
    const results = await cacheNoteCovers(body.noteIds || [], body.projectId, Math.min(20, Math.max(1, Number(body.limit || 12))));
    return Response.json({ ok: true, count: results.length, results });
  } catch (error) {
    return jsonError(error instanceof Error ? error.message : '封面抓取失败', 500);
  }
}

import { apiUser, requireProjectAccess, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { projectId } from '@/lib/projects';

export const dynamic = 'force-dynamic';

export async function GET(request: Request) {
  const url = new URL(request.url);
  const rawProject = url.searchParams.get('projectId');
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, rawProject, 'read')
    : (await apiUser() ? { ok: true, status: 200, error: '', context: { projectId: String(rawProject || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  await ensureSchema();
  const d1 = db();
  const view = (url.searchParams.get('view') || 'registry').trim();
  const query = (url.searchParams.get('query') || '').trim();
  const from = (url.searchParams.get('from') || '').trim();
  const to = (url.searchParams.get('to') || '').trim();
  const source = (url.searchParams.get('source') || '').trim();
  const scope = (url.searchParams.get('scope') || '').trim();
  const status = (url.searchParams.get('status') || '').trim();
  const category = (url.searchParams.get('category') || '').trim();
  const monitored = (url.searchParams.get('monitored') || '').trim();
  const hasMetrics = (url.searchParams.get('hasMetrics') || '').trim();
  const replyPending = url.searchParams.get('replyPending') === '1';
  const sort = (url.searchParams.get('sort') || '').trim();
  const order = (url.searchParams.get('order') || 'desc').toLowerCase() === 'asc' ? 'ASC' : 'DESC';
  const page = Math.max(1, parseInt(url.searchParams.get('page') || '1', 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(url.searchParams.get('pageSize') || '20', 10)));
  const offset = (page - 1) * pageSize;

  const conditions = ['pn.project_id = ?'];
  const params: unknown[] = [project];

  if (view === 'publishing') {
    conditions.push("pn.source_type IN ('owned', 'commercial')");
  }

  if (replyPending) {
    conditions.push(`EXISTS (
      SELECT 1 FROM key_comments reply
      WHERE reply.note_id = n.id AND reply.project_id = pn.project_id
        AND reply.treatment_status = '待处理' AND reply.action = '需达人回复'
    )`);
  }

  if (query) {
    conditions.push('(n.title LIKE ? OR n.author LIKE ? OR n.id LIKE ?)');
    const q = '%' + query + '%';
    params.push(q, q, q);
  }
  if (from) {
    conditions.push('(date(COALESCE(n.published_at, pn.last_fetched_at, pn.added_at)) >= date(?) OR COALESCE(n.published_at, pn.last_fetched_at, pn.added_at) IS NULL)');
    params.push(from);
  }
  if (to) {
    conditions.push('(date(COALESCE(n.published_at, pn.last_fetched_at, pn.added_at)) <= date(?) OR COALESCE(n.published_at, pn.last_fetched_at, pn.added_at) IS NULL)');
    params.push(to);
  }
  if (source) {
    conditions.push('pn.source_type = ?');
    params.push(source);
  }
  if (scope) {
    conditions.push('pn.product_scope = ?');
    params.push(scope);
  }
  if (status) {
    if (status === 'supplement' || status.includes('补充')) {
      conditions.push("pn.status LIKE '%补充%'");
    } else {
      conditions.push('pn.status = ?');
      params.push(status);
    }
  }
  if (category) {
    conditions.push('p.category1 = ?');
    params.push(category);
  }
  if (monitored === '1') {
    conditions.push("(pn.status != '待抓取' OR pn.last_fetched_at IS NOT NULL)");
  } else if (monitored === '0') {
    conditions.push("(pn.status = '待抓取' AND pn.last_fetched_at IS NULL)");
  }
  if (hasMetrics === '1') {
    conditions.push('p.read_count > 0 AND p.interaction_count > 0');
  } else if (hasMetrics === '0') {
    conditions.push('(p.read_count IS NULL OR p.read_count = 0 OR p.interaction_count IS NULL OR p.interaction_count = 0)');
  }

  const whereClause = ' WHERE ' + conditions.join(' AND ');

  let orderBy = 'COALESCE(pn.last_fetched_at, n.published_at, pn.added_at) DESC, n.id DESC';
  if (sort === 'reads' || sort === 'readCount') {
    orderBy = 'p.read_count ' + order + ', n.id DESC';
  } else if (sort === 'interactions' || sort === 'interactionCount') {
    orderBy = 'p.interaction_count ' + order + ', n.id DESC';
  } else if (sort === 'comments' || sort === 'commentTotal') {
    orderBy = 'pn.comment_total ' + order + ', n.id DESC';
  } else if (sort === 'publishedAt') {
    orderBy = 'COALESCE(n.published_at, pn.added_at) ' + order + ', n.id DESC';
  } else if (sort === 'lastFetchedAt') {
    orderBy = 'pn.last_fetched_at ' + order + ', n.id DESC';
  } else if (sort === 'cpe') {
    orderBy = 'CASE WHEN p.interaction_count > 0 AND p.note_price IS NOT NULL THEN 0 ELSE 1 END, (p.note_price / p.interaction_count) ' + order + ', n.id DESC';
  }

  const countSql = 'SELECT COUNT(*) AS total FROM notes n JOIN project_notes pn ON pn.note_id = n.id LEFT JOIN note_profiles p ON p.note_id = n.id' + whereClause;

  const summarySql = `
    SELECT 
      COUNT(*) AS total,
      SUM(CASE WHEN (p.cover_url IS NOT NULL AND p.cover_url != '') THEN 1 ELSE 0 END) AS coverCount,
      SUM(CASE WHEN (p.category1 IS NOT NULL AND p.category1 != '') THEN 1 ELSE 0 END) AS categoryCount,
      SUM(CASE WHEN (p.cover_url IS NOT NULL AND p.cover_url != '') AND (p.category1 IS NOT NULL AND p.category1 != '') THEN 1 ELSE 0 END) AS basicProfileCount,
      SUM(CASE WHEN (p.read_count IS NOT NULL AND p.read_count > 0) AND (p.interaction_count IS NOT NULL AND p.interaction_count > 0) THEN 1 ELSE 0 END) AS performanceMetricCount,
      SUM(CASE WHEN (p.read_count IS NOT NULL AND p.read_count > 0) OR (p.interaction_count IS NOT NULL AND p.interaction_count > 0) THEN 1 ELSE 0 END) AS anyPerformanceMetricCount,
      SUM(CASE WHEN (n.url IS NOT NULL AND n.url != '') THEN 1 ELSE 0 END) AS linkCount,
      SUM(CASE WHEN (p.creator_level IS NOT NULL AND p.creator_level != '') THEN 1 ELSE 0 END) AS creatorLevelCount,
      SUM(CASE WHEN (p.read_count IS NOT NULL AND p.read_count > 0) THEN 1 ELSE 0 END) AS readMetricCount,
      SUM(CASE WHEN (p.interaction_count IS NOT NULL AND p.interaction_count > 0) THEN 1 ELSE 0 END) AS interactionMetricCount,
      SUM(CASE WHEN pn.source_type = 'owned' AND COALESCE(p.cooperation, 0) != 1 THEN 1 ELSE 0 END) AS ownedOrganicCount,
      SUM(CASE WHEN pn.source_type = 'commercial' OR p.cooperation = 1 THEN 1 ELSE 0 END) AS commercialCount,
      SUM(CASE WHEN pn.source_type NOT IN ('owned', 'commercial') AND COALESCE(p.cooperation, 0) != 1 THEN 1 ELSE 0 END) AS externalNaturalCount,
      SUM(CASE WHEN pn.source_type IN ('owned', 'commercial') OR COALESCE(p.cooperation, 0) = 1 THEN 1 ELSE 0 END) AS ownedCount,
      COUNT(DISTINCT CASE WHEN (n.published_at IS NOT NULL AND n.published_at != '') AND (pn.source_type IN ('owned', 'commercial') OR COALESCE(p.cooperation, 0) = 1) THEN n.id END) AS operationalPublishedCount,
      SUM(CASE WHEN pn.source_type = 'owned' AND (n.published_at IS NOT NULL AND n.published_at != '') THEN 1 ELSE 0 END) AS ownedPublishedCount,
      SUM(CASE WHEN (n.published_at IS NOT NULL AND n.published_at != '') THEN 1 ELSE 0 END) AS publishedCount,
      SUM(CASE WHEN pn.source_type = 'keyword_scan' THEN 1 ELSE 0 END) AS scanCount,
      SUM(CASE WHEN (p.cover_url IS NOT NULL AND p.cover_url != '') 
                AND (p.read_count IS NOT NULL AND p.read_count > 0) 
                AND (p.category1 IS NOT NULL AND p.category1 != '') THEN 1 ELSE 0 END) AS completeCount,
      SUM(CASE WHEN pn.status = '符合且能汇报' THEN 1 ELSE 0 END) AS reportableCount,
      SUM(CASE WHEN pn.status = '符合基础要求' THEN 1 ELSE 0 END) AS baseCount,
      SUM(CASE WHEN pn.status LIKE '%补充%' THEN 1 ELSE 0 END) AS supplementCount,
      SUM((SELECT COUNT(*) FROM key_comments reply
        WHERE reply.note_id = n.id AND reply.project_id = pn.project_id
          AND reply.treatment_status = '待处理' AND reply.action = '需达人回复'
      )) AS replyPendingCount,
      SUM(CASE WHEN pn.status != '待抓取' OR pn.last_fetched_at IS NOT NULL THEN 1 ELSE 0 END) AS fetchedCount,
      SUM(CASE WHEN pn.status = '待抓取' AND pn.last_fetched_at IS NULL THEN 1 ELSE 0 END) AS unfetchedCount,
      COALESCE(SUM(pn.comment_total), 0) AS totalComments,
      COALESCE(SUM(p.read_count), 0) AS totalReads,
      COALESCE(SUM(p.interaction_count), 0) AS totalInteractions
    FROM notes n
    JOIN project_notes pn ON pn.note_id = n.id
    LEFT JOIN note_profiles p ON p.note_id = n.id
    WHERE pn.project_id = ?
  `;

  const listSql = `
    SELECT 
      n.id, n.url, n.author, 
      CASE WHEN n.title = '#N/A' OR n.title IS NULL OR n.title = '' THEN COALESCE(NULLIF(p.category1, ''), '启萃笔记') ELSE n.title END AS title,
      n.published_at AS publishedAt,
      pn.source_type AS sourceType, pn.pipeline, pn.level, pn.product_scope AS productScope,
      pn.status, pn.last_fetched_at AS lastFetchedAt,
      pn.comment_total AS commentTotal, pn.positive_count AS positiveCount,
      pn.negative_count AS negativeCount, pn.question_count AS questionCount,
      pn.brand_mention_top5 AS brandMentionTop5, pn.added_at AS addedAt,
      CASE WHEN p.cover_url LIKE 'http://%' THEN 'https://' || SUBSTR(p.cover_url, 8) ELSE p.cover_url END AS coverUrl,
      p.category1, p.category2, p.note_type AS noteType,
      p.read_count AS readCount, p.interaction_count AS interactionCount,
      p.like_count AS likeCount, p.favorite_count AS favoriteCount,
      p.creator_level AS creatorLevel, p.brand, p.note_price AS notePrice,
      CASE WHEN p.interaction_count > 0 AND p.note_price IS NOT NULL THEN ROUND(p.note_price / p.interaction_count, 2) ELSE NULL END AS cpe,
      snap.captured_at AS latestSnapshotTime,
      snap.l1_count AS latestL1Count,
      snap.l2_count AS latestL2Count,
      snap.total_count AS latestSnapshotTotal,
      prev_snap.total_count AS prevSnapshotTotal,
      CASE WHEN snap.total_count IS NULL THEN NULL WHEN prev_snap.total_count IS NULL THEN NULL ELSE (snap.total_count - prev_snap.total_count) END AS commentDelta,
      CASE WHEN pn.status != '待抓取' OR pn.last_fetched_at IS NOT NULL OR snap.captured_at IS NOT NULL THEN 1 ELSE 0 END AS isFetched,
      CASE WHEN (p.cover_url IS NOT NULL AND p.cover_url != '') 
            AND (p.read_count IS NOT NULL AND p.read_count > 0) 
            AND (p.category1 IS NOT NULL AND p.category1 != '') THEN 1 ELSE 0 END AS isProfileComplete,
      COALESCE(kc.pendingCount, 0) AS pendingRiskCount,
      COALESCE(kc.replyPendingCount, 0) AS replyPendingCount
    FROM notes n
    JOIN project_notes pn ON pn.note_id = n.id
    LEFT JOIN note_profiles p ON p.note_id = n.id
    LEFT JOIN (
      SELECT note_id, captured_at, l1_count, l2_count, total_count,
             ROW_NUMBER() OVER(PARTITION BY note_id ORDER BY captured_at DESC) AS rn
      FROM comment_snapshots WHERE project_id = ?
    ) snap ON snap.note_id = n.id AND snap.rn = 1
    LEFT JOIN (
      SELECT note_id, total_count,
             ROW_NUMBER() OVER(PARTITION BY note_id ORDER BY captured_at DESC) AS rn
      FROM comment_snapshots WHERE project_id = ?
    ) prev_snap ON prev_snap.note_id = n.id AND prev_snap.rn = 2
    LEFT JOIN (
      SELECT note_id, COUNT(*) AS pendingCount,
        SUM(CASE WHEN action = '需达人回复' THEN 1 ELSE 0 END) AS replyPendingCount
      FROM key_comments
      WHERE project_id = ? AND treatment_status = '待处理'
      GROUP BY note_id
    ) kc ON kc.note_id = n.id
    ` + whereClause + `
    ORDER BY ` + orderBy + `
    LIMIT ? OFFSET ?
  `;

  const coverageFeedbackSql = `
    SELECT 
      COALESCE(NULLIF(p.category1, ''), '待补充内容方向') AS direction,
      SUM(CASE WHEN pn.source_type = 'owned' AND COALESCE(p.cooperation, 0) != 1 THEN 1 ELSE 0 END) AS owned,
      SUM(CASE WHEN pn.source_type = 'commercial' OR p.cooperation = 1 THEN 1 ELSE 0 END) AS commercial,
      SUM(CASE WHEN pn.source_type NOT IN ('owned', 'commercial') AND COALESCE(p.cooperation, 0) != 1 THEN 1 ELSE 0 END) AS natural,
      COALESCE(SUM(CASE WHEN pn.source_type NOT IN ('owned', 'commercial') AND COALESCE(p.cooperation, 0) != 1 THEN p.interaction_count ELSE 0 END), 0) AS interactions,
      COALESCE(SUM(CASE WHEN pn.source_type NOT IN ('owned', 'commercial') AND COALESCE(p.cooperation, 0) != 1 THEN pn.comment_total ELSE 0 END), 0) AS comments
    FROM notes n
    JOIN project_notes pn ON pn.note_id = n.id
    LEFT JOIN note_profiles p ON p.note_id = n.id
    WHERE pn.project_id = ?
    GROUP BY direction
    ORDER BY natural DESC, owned DESC
  `;

  const [totalRow, summaryRow, itemsRows, feedbackRows] = await Promise.all([
    d1.prepare(countSql).bind(...params).first<{ total: number }>(),
    d1.prepare(summarySql).bind(project).first<{
      total: number;
      coverCount: number;
      categoryCount: number;
      basicProfileCount: number;
      performanceMetricCount: number;
      anyPerformanceMetricCount: number;
      linkCount: number;
      creatorLevelCount: number;
      readMetricCount: number;
      interactionMetricCount: number;
      ownedOrganicCount: number;
      externalNaturalCount: number;
      ownedCount: number;
      commercialCount: number;
      operationalPublishedCount: number;
      ownedPublishedCount: number;
      publishedCount: number;
      scanCount: number;
      completeCount: number;
      reportableCount: number;
      baseCount: number;
      supplementCount: number;
      replyPendingCount: number;
      fetchedCount: number;
      unfetchedCount: number;
      totalComments: number;
      totalReads: number;
      totalInteractions: number;
    }>(),
    d1.prepare(listSql).bind(project, project, project, ...params, pageSize, offset).all(),
    d1.prepare(coverageFeedbackSql).bind(project).all<{ direction: string; owned: number; commercial: number; natural: number; interactions: number; comments: number }>(),
  ]);

  const total = Number(totalRow?.total || 0);
  const summaryTotal = Number(summaryRow?.total || 0);
  const basicProfileCount = Number(summaryRow?.basicProfileCount || 0);
  const missingBasicProfileCount = Math.max(0, summaryTotal - basicProfileCount);
  const performanceMetricCount = Number(summaryRow?.performanceMetricCount || 0);
  const missingPerformanceCount = Math.max(0, summaryTotal - performanceMetricCount);

  const summary = {
    total: summaryTotal,
    coverCount: Number(summaryRow?.coverCount || 0),
    categoryCount: Number(summaryRow?.categoryCount || 0),
    basicProfileCount,
    missingBasicProfileCount,
    performanceMetricCount,
    missingPerformanceCount,
    anyPerformanceMetricCount: Number(summaryRow?.anyPerformanceMetricCount || 0),
    linkCount: Number(summaryRow?.linkCount || 0),
    creatorLevelCount: Number(summaryRow?.creatorLevelCount || 0),
    readMetricCount: Number(summaryRow?.readMetricCount || 0),
    interactionMetricCount: Number(summaryRow?.interactionMetricCount || 0),
    ownedOrganicCount: Number(summaryRow?.ownedOrganicCount || 0),
    ownedCommercialCount: Number(summaryRow?.commercialCount || 0),
    externalNaturalCount: Number(summaryRow?.externalNaturalCount || 0),
    ownedCount: Number(summaryRow?.ownedCount || 0),
    commercialCount: Number(summaryRow?.commercialCount || 0),
    operationalPublishedCount: Number(summaryRow?.operationalPublishedCount || 0),
    ownedPublishedCount: Number(summaryRow?.ownedPublishedCount || 0),
    publishedCount: Number(summaryRow?.publishedCount || 0),
    scanCount: Number(summaryRow?.scanCount || 0),
    completeCount: Number(summaryRow?.completeCount || 0),
    missingProfileCount: missingPerformanceCount,
    reportableCount: Number(summaryRow?.reportableCount || 0),
    baseCount: Number(summaryRow?.baseCount || 0),
    supplementCount: Number(summaryRow?.supplementCount || 0),
    replyPendingCount: Number(summaryRow?.replyPendingCount || 0),
    fetchedCount: Number(summaryRow?.fetchedCount || 0),
    unfetchedCount: Number(summaryRow?.unfetchedCount || 0),
    totalComments: Number(summaryRow?.totalComments || 0),
    totalReads: Number(summaryRow?.totalReads || 0),
    totalInteractions: Number(summaryRow?.totalInteractions || 0),
  };

  const enrichedItems = ((itemsRows.results || []) as Array<Record<string, unknown>>).map((row) => {

    const coverUrl = `/api/note-covers?resolve=1&projectId=${encodeURIComponent(project)}&noteId=${encodeURIComponent(String(row.id))}`;
    const rawTitle = typeof row.title === 'string' ? row.title : '';
    const title = (rawTitle && rawTitle !== '#N/A' && rawTitle !== '启萃笔记') ? rawTitle : '标题待同步';
    const rawAuthor = typeof row.author === 'string' ? row.author : '';
    const author = (rawAuthor && rawAuthor !== '未知作者') ? rawAuthor : '作者待同步';
    return {
      ...row,
      coverUrl,
      title,
      author,
    };
  });

  return Response.json({
    ok: true,
    items: enrichedItems,
    total,
    page,
    pageSize,
    summary: {
      ...summary,
      coverCount: summary.coverCount,
    },
    coverageFeedback: feedbackRows.results || [],
  });
}

import { apiUser, requireProjectAccess, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { DEFAULT_RULES } from '@/lib/classify';
import { getSetting } from '@/lib/ops';
import { projectId } from '@/lib/projects';

export const dynamic = 'force-dynamic';

type CacheEntry = { json: string; timestamp: number };
const memoryCache = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 120_000;

export function invalidateOpsCache(project?: string) {
  if (!project) {
    memoryCache.clear();
    return;
  }
  for (const k of memoryCache.keys()) {
    if (k.startsWith(`ops:${project}:`)) {
      memoryCache.delete(k);
    }
  }
}

export async function GET(request: Request) {
  const url = new URL(request.url);
  const rawProject = url.searchParams.get('projectId');
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, rawProject, 'read')
    : (await apiUser() ? { ok: true, status: 200, error: '', context: { projectId: String(rawProject || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  await ensureSchema();
  const d1 = db();
  const visibility = url.searchParams.get('visibility') || '';
  const fresh = url.searchParams.get('fresh') === '1' || Boolean(url.searchParams.get('_t'));
  const cacheKey = `ops:${project}:${visibility}`;

  if (fresh) {
    for (const k of memoryCache.keys()) {
      if (k.startsWith(`ops:${project}:`)) {
        memoryCache.delete(k);
      }
    }
  } else {
  const cached = memoryCache.get(cacheKey);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
    return new Response(cached.json, {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Cache-Control': 'private, max-age=60, stale-while-revalidate=180',
        'X-Cache': 'HIT',
      },
    });
  }
  }

  const supplierSql = `SELECT id,note_id AS noteId,note_url AS noteUrl,creator,planned_content AS plannedContent,
    comment_format AS commentFormat,visibility,matched_content AS matchedContent,verified_at AS verifiedAt
    FROM supplier_comments WHERE project_id=? ${visibility ? 'AND visibility=?' : ''} ORDER BY COALESCE(verified_at,'') DESC,id DESC LIMIT 120`;

  const [
    jobs,
    logs,
    supplier,
    supplierFeatures,
    categories,
    rules,
    acceptance,
    goals,
    growth,
    reviewRules,
    reports,
    completedJobsRow,
  ] = await Promise.all([
    d1.prepare('SELECT id,type,title,status,progress,total,succeeded,failed,message,created_at AS createdAt,finished_at AS finishedAt FROM jobs WHERE project_id=? ORDER BY created_at DESC LIMIT 40').bind(project).all(),
    d1.prepare('SELECT id,action,target_type AS targetType,target_id AS targetId,detail,actor_user_id AS actorUserId,created_at AS createdAt FROM action_logs WHERE project_id=? ORDER BY created_at DESC LIMIT 60').bind(project).all(),
    visibility ? d1.prepare(supplierSql).bind(project, visibility).all() : d1.prepare(supplierSql).bind(project).all(),
    d1.prepare(`SELECT visibility,COUNT(*) AS count,ROUND(AVG(LENGTH(planned_content)),1) AS avgLength,
      ROUND(AVG(CASE WHEN planned_content LIKE '%，%' OR planned_content LIKE '%,%' THEN 1.0 ELSE 0 END)*100,1) AS commaRate,
      ROUND(AVG(CASE WHEN LENGTH(planned_content)>=18 OR planned_content GLOB '*[0-9]*' THEN 1.0 ELSE 0 END)*100,1) AS detailRate
      FROM supplier_comments WHERE project_id=? AND visibility!='待核验' GROUP BY visibility`).bind(project).all(),
    d1.prepare(`SELECT category,sentiment,COUNT(*) AS count FROM key_comments WHERE project_id=? AND disappeared_at IS NULL GROUP BY category,sentiment ORDER BY count DESC LIMIT 12`).bind(project).all(),
    getSetting('rules', DEFAULT_RULES, project),
    getSetting('acceptance', { reportCount: 200, baseCount: 30, brandTopRate: 0.4, freshnessHours: 24, supplierSimilarity: 0.58 }, project),
    getSetting('goals', { workTarget: 0, workCompleted: 0, monthlyTarget: 0, quarterlyTarget: 0, publishTarget: 0, budgetTarget: 0, commentTarget: 0 }, project),
    getSetting('growth', { watchKeywords: [], inspirations: [], seedNoteIds: [], thresholds: { breakoutInteractions: 1000, seedScore: 65, ctr: 0.15, cpuv: 0.7 } }, project),
    d1.prepare(`SELECT id,name,keywords,sentiment,category,action,priority,enabled,updated_at AS updatedAt FROM review_rules WHERE project_id=? ORDER BY priority,updated_at DESC`).bind(project).all(),
    d1.prepare(`SELECT id,title,period_start AS periodStart,period_end AS periodEnd,status,summary_json AS summaryJson,created_at AS createdAt,updated_at AS updatedAt FROM saved_reports WHERE project_id=? ORDER BY updated_at DESC LIMIT 30`).bind(project).all(),
    d1.prepare(`SELECT COUNT(*) AS count FROM jobs WHERE project_id=? AND status='已完成'`).bind(project).first<{ count: number }>(),
  ]);

  const actualCompleted = Number(completedJobsRow?.count || 0);
  const resolvedGoals = {
    ...goals,
    workCompleted: actualCompleted,
  };

  const payload = {
    ok: true,
    jobs: jobs.results,
    logs: logs.results,
    supplier: supplier.results,
    supplierFeatures: supplierFeatures.results,
    categories: categories.results,
    reviewRules: reviewRules.results,
    reports: reports.results,
    settings: { rules, acceptance, goals: resolvedGoals, growth },
  };

  const jsonStr = JSON.stringify(payload);
  memoryCache.set(cacheKey, { json: jsonStr, timestamp: Date.now() });

  return new Response(jsonStr, {
    status: 200,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': fresh ? 'no-cache, no-store, must-revalidate' : 'private, max-age=60, stale-while-revalidate=180',
      'X-Cache': 'MISS',
    },
  });
}

import { getAuthenticatedUser, requireProjectAccess, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { projectId } from '@/lib/projects';
import { projectReadiness } from '@/lib/onboarding';
import { transformMappedRows, type FieldMappingRule, type MappingContext } from '@/lib/field-mapping';

export const dynamic = 'force-dynamic';
const text = (value: unknown) => String(value || '').trim();
const slug = (value: string) =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 32) || `project-${crypto.randomUUID().slice(0, 8)}`;

export async function GET(request?: Request) {
  const user = await getAuthenticatedUser(request);
  if (!user) return jsonError('请先登录', 401);

  await ensureSchema();
  const d1 = db();

  const url = request ? new URL(request.url) : null;
  const targetProjectId = url?.searchParams.get('projectId');
  if (targetProjectId) {
    const access = await requireProjectAccess(request!, targetProjectId, 'read');
    if (!access.ok) return jsonError(access.error!, access.status!);
    const pId = access.context!.projectId;

    const [project, members, availableUsers, onboarding] = await Promise.all([
      d1.prepare(`SELECT p.id, p.name, p.spu, p.brand, p.category, p.description, p.status, p.color,
        p.start_at AS startAt, p.end_at AS endAt, p.org_id AS orgId, p.department_id AS departmentId,
        p.client_id AS clientId, p.owner_id AS ownerId, p.template_id AS templateId,
        p.is_archived AS isArchived, p.onboarding_status AS onboardingStatus,
        p.updated_at AS updatedAt,
        d.name AS departmentName, c.name AS clientName, t.name AS templateName
        FROM projects p
        LEFT JOIN departments d ON d.id=p.department_id
        LEFT JOIN clients c ON c.id=p.client_id
        LEFT JOIN project_templates t ON t.id=p.template_id
        WHERE p.id=?`).bind(pId).first(),
      d1.prepare(`SELECT pm.id, pm.project_id AS projectId, pm.user_id AS userId, pm.role,
        COALESCE(u.name, pm.user_id) AS name, COALESCE(u.email, '') AS email, u.department_id AS departmentId
        FROM project_members pm
        LEFT JOIN users u ON u.id=pm.user_id
        WHERE pm.project_id=? ORDER BY pm.created_at ASC`).bind(pId).all(),
      d1.prepare('SELECT id, name, email, role, department_id AS departmentId FROM users ORDER BY name').all(),
      d1.prepare('SELECT current_step AS currentStep, completed_steps_json AS completedStepsJson, selected_template_id AS selectedTemplateId FROM project_onboarding WHERE project_id=?').bind(pId).first(),
    ]);

    return Response.json({
      ok: true,
      project,
      members: members.results || [],
      availableUsers: availableUsers.results || [],
      onboarding,
      currentUser: access.context!.user,
      projectRole: access.context!.projectRole,
      readiness: await projectReadiness(pId, (() => { try { return JSON.parse((onboarding as { completedStepsJson?: string })?.completedStepsJson || '[]'); } catch { return []; } })()),
    });
  }

  const isPlatformAdmin = user.role === 'platform_admin';
  const filterClause = isPlatformAdmin
    ? '1=1'
    : `(p.id IN (SELECT project_id FROM project_members WHERE user_id='${user.userId}') OR p.created_by='${user.userId}' OR p.owner_id='${user.userId}')`;

  const [projects, sources, departments, clients, templates] = await Promise.all([
    d1
      .prepare(
        `SELECT p.id, p.name, p.spu, p.brand, p.category, p.description, p.status, p.color,
        p.start_at AS startAt, p.end_at AS endAt, p.org_id AS orgId, p.department_id AS departmentId,
        p.client_id AS clientId, p.owner_id AS ownerId, p.template_id AS templateId,
        p.is_archived AS isArchived, p.onboarding_status AS onboardingStatus,
        p.updated_at AS updatedAt,
        COUNT(DISTINCT pn.note_id) AS noteCount,
        SUM(CASE WHEN pn.status='符合且能汇报' THEN 1 ELSE 0 END) AS reportableCount,
        d.name AS departmentName,
        c.name AS clientName,
        t.name AS templateName
        FROM projects p
        LEFT JOIN project_notes pn ON pn.project_id=p.id
        LEFT JOIN departments d ON d.id=p.department_id
        LEFT JOIN clients c ON c.id=p.client_id
        LEFT JOIN project_templates t ON t.id=p.template_id
        WHERE ${filterClause}
        GROUP BY p.id
        ORDER BY CASE p.status WHEN '进行中' THEN 0 WHEN '筹备中' THEN 1 WHEN '已结束' THEN 2 ELSE 3 END, p.updated_at DESC`
      )
      .all(),
    d1
      .prepare(
        `SELECT s.id, s.project_id AS projectId, s.type, s.name, s.spreadsheet, s.sheet_id AS sheetId,
        s.range, s.kind, s.sync_frequency AS syncFrequency, s.status, s.last_synced_at AS lastSyncedAt,
        s.last_row_count AS lastRowCount, s.mapping_json AS mappingJson, s.last_error AS lastError,
        s.updated_at AS updatedAt
        FROM data_sources s
        JOIN projects p ON p.id=s.project_id
        WHERE ${filterClause}
        ORDER BY s.updated_at DESC`
      )
      .all(),
    d1.prepare('SELECT id, name FROM departments ORDER BY name').all(),
    d1.prepare('SELECT id, name, industry FROM clients ORDER BY name').all(),
    d1.prepare('SELECT id, name, description, icon, modules_json AS modulesJson FROM project_templates ORDER BY name').all(),
  ]);

  return Response.json({
    ok: true,
    projects: projects.results,
    sources: sources.results,
    metadata: {
      departments: departments.results,
      clients: clients.results,
      templates: templates.results,
      currentUser: user,
    },
  });
}

export async function POST(request: Request) {
  let body: Record<string, unknown> = {};
  try {
    body = (await request.json()) as Record<string, unknown>;
  } catch {
    return jsonError('无效的请求数据');
  }

  const action = text(body.action);
  const now = new Date().toISOString();
  await ensureSchema();
  const d1 = db();

  if (action === 'create') {
    const user = await getAuthenticatedUser(request);
    if (!user) return jsonError('请先登录', 401);

    const name = text(body.name);
    if (!name) return jsonError('请填写项目名称');

    const templateId = text(body.templateId) || 'general_workbench';
    const departmentId = text(body.departmentId) || 'dept-general';
    const clientId = text(body.clientId) || null;
    const ownerId = text(body.ownerId) || user.userId;
    const status = text(body.status) || '筹备中';
    const color = text(body.color) || '#1769d5';
    const description = text(body.description);
    const spu = text(body.spu);
    const brand = text(body.brand);
    const category = text(body.category);
    const startAt = text(body.startAt) || null;
    const endAt = text(body.endAt) || null;

    let id = text(body.id) ? slug(text(body.id)) : slug(name);
    const exists = await d1.prepare('SELECT id FROM projects WHERE id=?').bind(id).first();
    if (exists) id = `${id}-${Date.now().toString(36).slice(-4)}`;

    await d1
      .prepare(
        `INSERT INTO projects(id, name, spu, brand, category, description, status, color, start_at, end_at,
        org_id, department_id, client_id, owner_id, template_id, is_archived, onboarding_status, created_by, created_at, updated_at)
        VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'org-default', ?, ?, ?, ?, 0, 'source', ?, ?, ?)`
      )
      .bind(id, name, spu, brand, category, description, status, color, startAt, endAt, departmentId, clientId, ownerId, templateId, user.userId, now, now)
      .run();

    // Add creator as project administrator
    await d1
      .prepare(`INSERT OR IGNORE INTO project_members(id, project_id, user_id, role, created_at, updated_at) VALUES(?, ?, ?, 'project_admin', ?, ?)`)
      .bind(`${id}:${user.userId}`, id, user.userId, now, now)
      .run();

    // Initialize onboarding state
    await d1
      .prepare(`INSERT OR IGNORE INTO project_onboarding(project_id, current_step, completed_steps_json, selected_template_id, updated_at) VALUES(?, 'source', '["template"]', ?, ?)`)
      .bind(id, templateId, now)
      .run();

    // Create default dashboard from template
    const templateRow = await d1.prepare('SELECT default_dashboard_json FROM project_templates WHERE id=?').bind(templateId).first<{ default_dashboard_json: string }>();
    let cards: Array<Record<string, unknown>> = [];
    if (templateRow?.default_dashboard_json) {
      try {
        const parsed = JSON.parse(templateRow.default_dashboard_json) as { cards?: Array<Record<string, unknown>> };
        cards = parsed.cards || [];
      } catch {}
    }

    const dashboardId = `dash-${id}-default`;
    await d1
      .prepare(`INSERT OR IGNORE INTO dashboards(id, project_id, name, is_default, version, layout_json, status, created_at, updated_at) VALUES(?, ?, '默认看板', 1, 1, '[]', 'published', ?, ?)`)
      .bind(dashboardId, id, now, now)
      .run();

    for (const [index, card] of cards.entries()) {
      const cardId = `card-${id}-${card.id || index + 1}`;
      await d1
        .prepare(`INSERT OR IGNORE INTO dashboard_cards(id, dashboard_id, project_id, title, type, metric_keys_json, config_json, sort_order, created_at, updated_at) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        .bind(cardId, dashboardId, id, String(card.title || '指标卡'), String(card.type || 'metric_card'), JSON.stringify(card.metric ? [card.metric] : []), JSON.stringify(card), index, now, now)
        .run();
    }

    // Only configure marketing/comment pipelines if this project explicitly selected those templates!
    if (templateId === 'content_marketing') {
      const pipelines = [
        ['viral', '口碑爆文维护', 200],
        ['value_scan', '价值内容扫描', 60],
        ['commercial', '商业内容执行', 300],
      ] as const;
      await d1.batch(
        pipelines.map(([key, label, target]) =>
          d1.prepare(`INSERT INTO project_pipelines(id,project_id,key,name,target_count) VALUES(?,?,?,?,?)`).bind(`${id}:${key}`, id, key, label, target)
        )
      );
      if (brand || spu) {
        const rules = {
          brands: [brand, spu].filter(Boolean),
          competitors: [],
          positiveWords: ['好用', '推荐', '喜欢', '有效', '值得'],
          negativeWords: ['不好', '踩雷', '失望', '问题', '投诉'],
          questionWords: ['吗', '怎么', '多少', '哪里买'],
          sellingWords: ['出售', '加微', '低价出'],
          irrelevantWords: ['互赞', '打卡', '路过'],
          deleteCompetitorMentions: false,
        };
        await d1
          .prepare(`INSERT INTO project_settings(id,project_id,key,value,updated_at) VALUES(?,?,?,?,?)`)
          .bind(`${id}:rules`, id, 'rules', JSON.stringify(rules), now)
          .run();
      }
    } else if (templateId === 'comment_qc') {
      await d1
        .prepare(`INSERT INTO project_settings(id,project_id,key,value,updated_at) VALUES(?,?,?,?,?)`)
        .bind(`${id}:acceptance`, id, 'acceptance', JSON.stringify({ reportCount: 200, baseCount: 30, brandTopRate: 0.4, freshnessHours: 24, supplierSimilarity: 0.58 }), now)
        .run();
    }

    return Response.json({ ok: true, id, templateId });
  }

  // All other actions require existing project access check
  const rawId = body.projectId;
  const access = await requireProjectAccess(request, rawId, action === 'delete' ? 'admin' : action === 'restore' ? 'restore' : 'manage');
  if (!access.ok) return jsonError(access.error!, access.status!);

  const id = access.context!.projectId;

  let readiness: Awaited<ReturnType<typeof projectReadiness>> | undefined;
  if (body.onboardingStatus === 'ready') {
    const previous = await d1.prepare('SELECT completed_steps_json FROM project_onboarding WHERE project_id=?').bind(id).first<{ completed_steps_json: string }>();
    let savedSteps: string[] = []; try { savedSteps = JSON.parse(previous?.completed_steps_json || '[]'); } catch {}
    const requestedSteps = [...savedSteps.filter(s => s === 'skip:members'), ...(Array.isArray(body.completedSteps) ? body.completedSteps.map(String) : [])];
    readiness = await projectReadiness(id, requestedSteps);
    if (!readiness.ready) return Response.json({ ok: false, error: '初始化必要条件未完成：' + readiness.blockedSteps.join('、'), readiness }, { status: 400 });
  }

  if (action === 'update_onboarding') {
    const statusVal = text(body.onboardingStatus) || 'pending';
    const completedSteps = readiness?.completedSteps || (Array.isArray(body.completedSteps) ? body.completedSteps.filter(s => s === 'skip:members') : []);
    const stepsJson = JSON.stringify(completedSteps);
    await d1.prepare(`UPDATE projects SET onboarding_status=?, updated_at=? WHERE id=?`).bind(statusVal, now, id).run();
    await d1.prepare(`UPDATE project_onboarding SET current_step=?, completed_steps_json=?, updated_at=? WHERE project_id=?`).bind(statusVal, stepsJson, now, id).run();
    return Response.json({ ok: true, id, onboardingStatus: statusVal, completedSteps });
  }

  if (action === 'update') {
    if (body.onboardingStatus !== undefined && body.name === undefined) {
      const statusVal = text(body.onboardingStatus) || 'ready';
      await d1.prepare(`UPDATE projects SET onboarding_status=?, updated_at=? WHERE id=?`).bind(statusVal, now, id).run();
      await d1.prepare(`UPDATE project_onboarding SET current_step='ready', completed_steps_json=?, updated_at=? WHERE project_id=?`).bind(JSON.stringify(readiness?.completedSteps || []), now, id).run();
      return Response.json({ ok: true, id, onboardingStatus: statusVal });
    }

    const existing = await d1.prepare('SELECT * FROM projects WHERE id=?').bind(id).first<Record<string, unknown>>();
    if (!existing) return jsonError('项目不存在', 404);

    const name = body.name !== undefined ? text(body.name) : (existing.name as string);
    if (!name) return jsonError('请填写项目名称');
    const spu = body.spu !== undefined ? text(body.spu) : (existing.spu as string);
    const brand = body.brand !== undefined ? text(body.brand) : (existing.brand as string);
    const category = body.category !== undefined ? text(body.category) : (existing.category as string);
    const description = body.description !== undefined ? text(body.description) : (existing.description as string);
    const status = body.status !== undefined ? text(body.status) : (existing.status as string);
    const color = body.color !== undefined ? text(body.color) : (existing.color as string);
    const departmentId = body.departmentId !== undefined ? text(body.departmentId) : (existing.department_id as string);
    const clientId = body.clientId !== undefined ? text(body.clientId) || null : (existing.client_id as string | null);
    const ownerId = body.ownerId !== undefined ? text(body.ownerId) : (existing.owner_id as string);
    const startAt = body.startAt !== undefined ? text(body.startAt) || null : (existing.start_at as string | null);
    const endAt = body.endAt !== undefined ? text(body.endAt) || null : (existing.end_at as string | null);
    const onboardingStatus = body.onboardingStatus !== undefined ? text(body.onboardingStatus) : (existing.onboarding_status as string);

    await d1
      .prepare(
        `UPDATE projects SET name=?, spu=?, brand=?, category=?, description=?, status=?, color=?,
        department_id=?, client_id=?, owner_id=?, start_at=?, end_at=?, onboarding_status=?, updated_at=? WHERE id=?`
      )
      .bind(
        name,
        spu,
        brand,
        category,
        description,
        status || '进行中',
        color || '#1769d5',
        departmentId || 'dept-general',
        clientId,
        ownerId || access.context!.user.userId,
        startAt,
        endAt,
        onboardingStatus || 'pending',
        now,
        id
      )
      .run();

    if (body.onboardingStatus === 'ready') {
      await d1.prepare(`UPDATE project_onboarding SET current_step='ready', completed_steps_json=?, updated_at=? WHERE project_id=?`).bind(JSON.stringify(readiness?.completedSteps || []), now, id).run();
    }
    return Response.json({ ok: true, id });
  }

  if (action === 'archive') {
    await d1.prepare(`UPDATE projects SET is_archived=1, status='已归档', archived_at=?, updated_at=? WHERE id=?`).bind(now, now, id).run();
    return Response.json({ ok: true, id, status: '已归档' });
  }

  if (action === 'restore') {
    await d1.prepare(`UPDATE projects SET is_archived=0, status='进行中', archived_at=NULL, updated_at=? WHERE id=?`).bind(now, id).run();
    return Response.json({ ok: true, id, status: '进行中' });
  }

  if (action === 'delete') {
    if (!access.context!.isPlatformAdmin) {
      return jsonError('仅平台超级管理员可执行彻底删除操作', 403);
    }
    await d1.batch([
      d1.prepare('DELETE FROM project_members WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM data_sources WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM dashboards WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM dashboard_cards WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM datasets WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM dataset_rows WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM sync_jobs WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM note_project_profiles WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM project_notes WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM supplier_comments WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM project_settings WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM projects WHERE id=?').bind(id),
    ]);
    return Response.json({ ok: true, id, deleted: true });
  }

  if (action === 'save_source') {
    const sourceId = text(body.id) || crypto.randomUUID();
    const ownership = await d1.prepare('SELECT project_id FROM data_sources WHERE id=?').bind(sourceId).first<{ project_id: string }>();
    if (ownership && ownership.project_id !== id) return jsonError('数据源不属于当前项目', 403);
    const name = text(body.name);
    if (!name) return jsonError('请填写数据源名称');
    let mapping = '{}';
    try {
      mapping = typeof body.mappingJson === 'string' ? JSON.stringify(JSON.parse(body.mappingJson)) : JSON.stringify(body.mappingJson || {});
    } catch {
      return jsonError('字段映射必须是合法 JSON');
    }
    const parsedMapping = JSON.parse(mapping) as { rules?: FieldMappingRule[]; context?: MappingContext };
    const rules = Array.isArray(parsedMapping) ? parsedMapping : parsedMapping.rules || [];
    const mappingErrors = transformMappedRows([], rules).errors;
    if (mappingErrors.length) return jsonError(mappingErrors.join('；'));
    if (parsedMapping.context && (parsedMapping.context.projectId !== id || parsedMapping.context.sheetId !== text(body.sheetId))) return jsonError('映射上下文与项目或工作表不匹配');
    if (!['general', 'dataset', 'owned', 'supplier'].includes(text(body.kind) || 'owned')) return jsonError('不支持的数据用途类型');
    const status = text(body.status) || (text(body.spreadsheet) && text(body.sheetId) ? '已连接' : '未连接');
    await d1
      .prepare(
        `INSERT INTO data_sources(id,project_id,type,name,spreadsheet,sheet_id,range,kind,sync_frequency,status,mapping_json,created_at,updated_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET
        type=excluded.type,name=excluded.name,spreadsheet=excluded.spreadsheet,sheet_id=excluded.sheet_id,range=excluded.range,kind=excluded.kind,sync_frequency=excluded.sync_frequency,status=excluded.status,mapping_json=excluded.mapping_json,updated_at=excluded.updated_at`
      )
      .bind(
        sourceId,
        id,
        text(body.type) || 'feishu_sheet',
        name,
        text(body.spreadsheet),
        text(body.sheetId),
        text(body.range),
        text(body.kind) || 'owned',
        text(body.syncFrequency) || 'manual',
        status,
        mapping,
        now,
        now
      )
      .run();
    return Response.json({ ok: true, id: sourceId });
  }

  if (action === 'remove_source') {
    const sourceId = text(body.id);
    if (!sourceId) return jsonError('缺少数据源 ID');
    await d1.prepare('DELETE FROM data_sources WHERE id=? AND project_id=?').bind(sourceId, id).run();
    return Response.json({ ok: true });
  }

  if (action === 'manage_member' || action === 'add_member' || action === 'update_member_role' || action === 'remove_member') {
    const targetUserId = text(body.userId);
    const role = text(body.role) || 'viewer';
    const subAction = action === 'remove_member' ? 'remove' : (text(body.subAction) || 'upsert');
    if (!targetUserId) return jsonError('缺少成员用户 ID');

    if (subAction === 'remove') {
      await d1.prepare('DELETE FROM project_members WHERE project_id=? AND user_id=?').bind(id, targetUserId).run();
      return Response.json({ ok: true, removed: true });
    }

    const existingMem = await d1.prepare('SELECT id FROM project_members WHERE project_id=? AND user_id=?').bind(id, targetUserId).first<{ id: string }>();
    if (existingMem) {
      await d1.prepare('UPDATE project_members SET role=?, updated_at=? WHERE id=?').bind(role, now, existingMem.id).run();
      return Response.json({ ok: true, memberId: existingMem.id, role });
    } else {
      const newId = `${id}:${targetUserId}`;
      await d1.prepare('INSERT INTO project_members(id, project_id, user_id, role, created_at, updated_at) VALUES(?, ?, ?, ?, ?, ?)').bind(newId, id, targetUserId, role, now, now).run();
      return Response.json({ ok: true, memberId: newId, role });
    }
  }

  return jsonError('不支持的操作');
}

