        d1.prepare('DELETE FROM project_settings WHERE project_id=?').bind(project),d1.prepare('DELETE FROM data_sources WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM integrations WHERE project_id=?').bind(project),d1.prepare('DELETE FROM review_rules WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM saved_reports WHERE project_id=?').bind(project),d1.prepare('DELETE FROM key_comments WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM source_accounts WHERE project_id=?').bind(project),d1.prepare('DELETE FROM api_endpoints WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM metric_bindings WHERE project_id=?').bind(project),d1.prepare('DELETE FROM metric_definitions WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM uploaded_assets WHERE project_id=?').bind(project),d1.prepare('DELETE FROM agent_steps WHERE run_id IN (SELECT id FROM agent_runs WHERE project_id=?)').bind(project),d1.prepare('DELETE FROM agent_runs WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM report_versions WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM comment_snapshots WHERE project_id=?').bind(project),d1.prepare('DELETE FROM supplier_comments WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM jobs WHERE project_id=?').bind(project),d1.prepare('DELETE FROM action_logs WHERE project_id=?').bind(project),
        d1.prepare('DELETE FROM projects WHERE id=?').bind(project),
      ]);return Response.json({ok:true});
    }
   if(action==='note_update'){
     const id=value(body.id);if(!id)return jsonError('缺少笔记 ID');
     const updates: string[] = [];
     const updateVals: unknown[] = [];
     if ('title' in body) { updates.push('title=?'); updateVals.push(value(body.title)); }
     if ('author' in body) { updates.push('author=?'); updateVals.push(value(body.author)); }
     if ('url' in body) { updates.push('url=?'); updateVals.push(value(body.url)); }
     if (updates.length > 0) {
       await d1.prepare(`UPDATE notes SET ${updates.join(',')} WHERE id=?`).bind(...updateVals, id).run();
     }
     const pnUpdates: string[] = [];
     const pnVals: unknown[] = [];
     if ('sourceType' in body) { pnUpdates.push('source_type=?'); pnVals.push(value(body.sourceType)); }
     if ('pipeline' in body) { pnUpdates.push('pipeline=?'); pnVals.push(value(body.pipeline)); }
     if ('level' in body) { pnUpdates.push('level=?'); pnVals.push(value(body.level)); }
     if ('productScope' in body) { pnUpdates.push('product_scope=?'); pnVals.push(value(body.productScope)); }
     if (pnUpdates.length > 0) {
       await d1.prepare(`UPDATE project_notes SET ${pnUpdates.join(',')} WHERE project_id=? AND note_id=?`).bind(...pnVals, project, id).run();
     }
     await logAction('更新笔记','note',id,'笔记基础资料已更新',project);
     return Response.json({ok:true});
   }
   if(action==='calibrate_acceptance'){
     const id=value(body.noteId || body.id);
     const newStatus=value(body.newStatus || body.status);
     const reason=value(body.reason)||'人工校正验收状态';
     if(!id||!newStatus)return jsonError('缺少笔记 ID 或新状态', 400);
     const oldRow=await d1.prepare('SELECT status FROM project_notes WHERE project_id=? AND note_id=?').bind(project,id).first<{status:string}>();
     if(!oldRow)return jsonError('未找到目标项目笔记记录', 404);
     const oldStatus=oldRow?.status||'待抓取';
     await d1.prepare('UPDATE project_notes SET status=? WHERE project_id=? AND note_id=?').bind(newStatus,project,id).run();
     await logAction('人工验收校正','acceptance',id,`原状态: ${oldStatus} -> 新状态: ${newStatus}，原因: ${reason}，操作人: ${user.displayName||user.userId}`,project);
     return Response.json({ok:true,oldStatus,newStatus});
   }
    if(action==='note_delete'){
      const id=value(body.id);if(!id)return jsonError('缺少笔记 ID');
      await d1.batch([d1.prepare('DELETE FROM project_notes WHERE project_id=? AND note_id=?').bind(project,id),d1.prepare('DELETE FROM key_comments WHERE project_id=? AND note_id=?').bind(project,id),d1.prepare('DELETE FROM comment_snapshots WHERE project_id=? AND note_id=?').bind(project,id)]);
      const remaining=await d1.prepare('SELECT COUNT(*) AS count FROM project_notes WHERE note_id=?').bind(id).first<{count:number}>();
      if(!Number(remaining?.count||0))await d1.batch([d1.prepare('DELETE FROM note_profiles WHERE note_id=?').bind(id),d1.prepare('DELETE FROM notes WHERE id=?').bind(id)]);
      await logAction('移出笔记','note',id,'笔记已从当前项目移除',project);return Response.json({ok:true});
    }
    if(action==='comment_update'){
      const id=value(body.id);await d1.prepare(`UPDATE key_comments SET sentiment=?,category=?,action=?,treatment_status=?,treatment_method=? WHERE id=? AND project_id=?`)
        .bind(value(body.sentiment)||'中立',value(body.category)||'其他',value(body.nextAction)||value(body.actionName)||'保留观察',value(body.treatmentStatus)||'待处理',value(body.treatmentMethod)||null,id,project).run();
      await logAction('更新评论判定','comment',id,'情感、分类或处置状态已修改',project);return Response.json({ok:true});
    }
    if(action==='comment_delete'){
      const id=value(body.id);await d1.prepare('DELETE FROM key_comments WHERE id=? AND project_id=?').bind(id,project).run();await logAction('移除关键评论','comment',id,'从关键评论清单移除',project);return Response.json({ok:true});
    }
    if(action==='supplier_upsert'){
      const id=number(body.id);const noteId=value(body.noteId);const content=value(body.plannedContent);if(!noteId||!content)return jsonError('请填写笔记 ID 和计划评论');
      if(id)await d1.prepare(`UPDATE supplier_comments SET note_url=?,creator=?,planned_content=?,comment_format=?,visibility=?,matched_content=? WHERE id=? AND project_id=?`).bind(value(body.noteUrl),value(body.creator),content,value(body.commentFormat),value(body.visibility)||'待核验',value(body.matchedContent)||null,id,project).run();
      else await d1.prepare(`INSERT INTO supplier_comments(project_id,external_key,note_id,note_url,creator,planned_content,comment_format,visibility) VALUES(?,?,?,?,?,?,?,?)`).bind(project,`${project}:${noteId}:${crypto.randomUUID()}`,noteId,value(body.noteUrl),value(body.creator),content,value(body.commentFormat),value(body.visibility)||'待核验').run();
      await logAction(id?'更新供应商评论':'新增供应商评论','supplier',String(id||noteId),content.slice(0,50),project);return Response.json({ok:true});
    }
    if(action==='supplier_delete'){
      const id=number(body.id);await d1.prepare('DELETE FROM supplier_comments WHERE id=? AND project_id=?').bind(id,project).run();await logAction('删除供应商评论','supplier',String(id),'供应商评论记录已删除',project);return Response.json({ok:true});
    }
    if(action==='pipeline_upsert'){
      const key=value(body.key)||value(body.id)||crypto.randomUUID().slice(0,8);const id=`${project}:${key}`;
      await d1.prepare(`INSERT INTO project_pipelines(id,project_id,key,name,target_count,delivered_count,budget,spent) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,target_count=excluded.target_count,delivered_count=excluded.delivered_count,budget=excluded.budget,spent=excluded.spent`)
        .bind(id,project,key,value(body.name)||'新执行主线',Math.max(0,number(body.targetCount)),Math.max(0,number(body.deliveredCount)),Math.max(0,number(body.budget)),Math.max(0,number(body.spent))).run();
      await logAction('保存执行主线','pipeline',key,value(body.name),project);return Response.json({ok:true,key});
    }
    if(action==='pipeline_delete'){
      const key=value(body.key)||value(body.id);await d1.prepare('DELETE FROM project_pipelines WHERE project_id=? AND key=?').bind(project,key).run();await logAction('删除执行主线','pipeline',key,'执行主线已删除',project);return Response.json({ok:true});
    }
    if(action==='job_upsert'){
      const id=value(body.id)||crypto.randomUUID();
      await d1.prepare(`INSERT INTO jobs(id,project_id,type,title,status,progress,total,succeeded,failed,message,created_at,finished_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,status=excluded.status,progress=excluded.progress,total=excluded.total,succeeded=excluded.succeeded,failed=excluded.failed,message=excluded.message,finished_at=excluded.finished_at`)
        .bind(id,project,value(body.type)||'manual',value(body.title)||'手工任务',value(body.status)||'待开始',number(body.progress),number(body.total),number(body.succeeded),number(body.failed),value(body.message),now,value(body.status)==='已完成'?now:null).run();
      await logAction(value(body.id)?'更新任务':'创建任务','job',id,value(body.title),project);return Response.json({ok:true,id});
    }
    if(action==='job_delete'){
      const id=value(body.id);await d1.prepare('DELETE FROM jobs WHERE id=? AND project_id=?').bind(id,project).run();await logAction('删除任务','job',id,'任务记录已删除',project);return Response.json({ok:true});
    }
    if(action==='rule_upsert'){
      const id=value(body.id)||crypto.randomUUID();
      await d1.prepare(`INSERT INTO review_rules(id,project_id,name,keywords,sentiment,category,action,priority,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,keywords=excluded.keywords,sentiment=excluded.sentiment,category=excluded.category,action=excluded.action,priority=excluded.priority,enabled=excluded.enabled,updated_at=excluded.updated_at`)
        .bind(id,project,value(body.name)||'补充规则',value(body.keywords),value(body.sentiment)||'中立',value(body.category)||'自定义规则',value(body.nextAction)||value(body.actionName)||'保留观察',number(body.priority,100),body.enabled===false?0:1,now,now).run();
      await logAction(value(body.id)?'更新补充规则':'新增补充规则','rule',id,value(body.name),project);return Response.json({ok:true,id});
    }
    if(action==='rule_delete'){
      const id=value(body.id);await d1.prepare('DELETE FROM review_rules WHERE id=? AND project_id=?').bind(id,project).run();await logAction('删除补充规则','rule',id,'规则已删除',project);return Response.json({ok:true});
    }
    if(action==='report_upsert'){
      const id=value(body.id)||crypto.randomUUID();const summary=typeof body.summary==='string'?body.summary:JSON.stringify(body.summary||{});
      await d1.prepare(`INSERT INTO saved_reports(id,project_id,title,period_start,period_end,status,summary_json,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,period_start=excluded.period_start,period_end=excluded.period_end,status=excluded.status,summary_json=excluded.summary_json,updated_at=excluded.updated_at`)
        .bind(id,project,value(body.title)||'项目动态复盘',value(body.periodStart)||null,value(body.periodEnd)||null,value(body.status)||'草稿',summary,user.userId,now,now).run();
      await logAction(value(body.id)?'更新报告':'保存报告','report',id,value(body.title),project);return Response.json({ok:true,id});
    }
    if(action==='report_delete'){
      const id=value(body.id);await d1.prepare('DELETE FROM saved_reports WHERE id=? AND project_id=?').bind(id,project).run();await logAction('删除报告','report',id,'保存报告已删除',project);return Response.json({ok:true});
    }
    return jsonError('不支持的资源操作');
  }catch(error){return jsonError(error instanceof Error?error.message:'资源操作失败',500)}
}

import { requireProjectAccess, apiUser, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { projectId } from '@/lib/projects';

export const dynamic = 'force-dynamic';

export async function GET(request: Request) {
  const url = new URL(request.url);
  const rawProject = url.searchParams.get('projectId');
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, rawProject, 'read')
    : (await apiUser() ? { ok: true, status: 200, error: '', context: { projectId: String(rawProject || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  await ensureSchema();
  const d1 = db();
  const visibility = (url.searchParams.get('visibility') || '').trim();
  const query = (url.searchParams.get('query') || '').trim();
  const from = (url.searchParams.get('from') || '').trim();
  const to = (url.searchParams.get('to') || '').trim();
  const page = Math.max(1, parseInt(url.searchParams.get('page') || '1', 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(url.searchParams.get('pageSize') || '20', 10)));
  const offset = (page - 1) * pageSize;

  const conditions = ['sc.project_id = ?'];
  const params: unknown[] = [project];

  if (visibility) {
    conditions.push('sc.visibility = ?');
    params.push(visibility);
  }
  if (query) {
    conditions.push('(sc.note_id LIKE ? OR sc.creator LIKE ? OR sc.planned_content LIKE ? OR sc.matched_content LIKE ?)');
    const q = '%' + query + '%';
    params.push(q, q, q, q);
  }
  if (from) {
    conditions.push('(sc.verified_at IS NOT NULL AND date(sc.verified_at) >= date(?))');
    params.push(from);
  }
  if (to) {
    conditions.push('(sc.verified_at IS NOT NULL AND date(sc.verified_at) <= date(?))');
    params.push(to);
  }

  const whereClause = ' WHERE ' + conditions.join(' AND ');

  const [totalRow, summaryRows, allSummaryRows, itemsRows] = await Promise.all([
    d1.prepare('SELECT COUNT(*) AS total FROM supplier_comments sc' + whereClause).bind(...params).first<{ total: number }>(),
    d1.prepare('SELECT COUNT(*) AS total, ' +
      "SUM(CASE WHEN visibility = '当前外显-原文一致' THEN 1 ELSE 0 END) AS exactCount, " +
      "SUM(CASE WHEN visibility = '当前外显-有修改' THEN 1 ELSE 0 END) AS modifiedCount, " +
      "SUM(CASE WHEN visibility = '当前未外显' THEN 1 ELSE 0 END) AS missingCount, " +
      "SUM(CASE WHEN visibility = '待核验' THEN 1 ELSE 0 END) AS pendingCount " +
      'FROM supplier_comments sc' + whereClause).bind(...params).first<{
      total: number;
      exactCount: number;
      modifiedCount: number;
      missingCount: number;
      pendingCount: number;
    }>(),
    d1.prepare('SELECT COUNT(*) AS total, ' +
      "SUM(CASE WHEN visibility = '当前外显-原文一致' THEN 1 ELSE 0 END) AS exactCount, " +
      "SUM(CASE WHEN visibility = '当前外显-有修改' THEN 1 ELSE 0 END) AS modifiedCount, " +
      "SUM(CASE WHEN visibility = '当前未外显' THEN 1 ELSE 0 END) AS missingCount, " +
      "SUM(CASE WHEN visibility = '待核验' THEN 1 ELSE 0 END) AS pendingCount " +
      'FROM supplier_comments sc WHERE sc.project_id = ?').bind(project).first<{
      total: number;
      exactCount: number;
      modifiedCount: number;
      missingCount: number;
      pendingCount: number;
    }>(),
    d1.prepare('SELECT id, note_id AS noteId, note_url AS noteUrl, creator, ' +
      'planned_content AS plannedContent, comment_format AS commentFormat, ' +
      'visibility, matched_content AS matchedContent, verified_at AS verifiedAt ' +
      'FROM supplier_comments sc' + whereClause + ' ' +
      "ORDER BY COALESCE(verified_at, '') DESC, id DESC " +
      'LIMIT ? OFFSET ?').bind(...params, pageSize, offset).all(),
  ]);

  const total = Number(totalRow?.total || 0);
  const summary = {
    total: Number(summaryRows?.total || 0),
    exactCount: Number(summaryRows?.exactCount || 0),
    modifiedCount: Number(summaryRows?.modifiedCount || 0),
    missingCount: Number(summaryRows?.missingCount || 0),
    pendingCount: Number(summaryRows?.pendingCount || 0),
  };
  const allSummary = {
    total: Number(allSummaryRows?.total || 0),
    exactCount: Number(allSummaryRows?.exactCount || 0),
    modifiedCount: Number(allSummaryRows?.modifiedCount || 0),
    missingCount: Number(allSummaryRows?.missingCount || 0),
    pendingCount: Number(allSummaryRows?.pendingCount || 0),
  };

  return Response.json({
    ok: true,
    items: itemsRows.results || [],
    total,
    page,
    pageSize,
    summary,
    allSummary,
  });
}

import { requireProjectAccess, apiUser, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { similarity } from '@/lib/store';
import { fetchAllComments } from '@/lib/xhs';
import { finishJob, logAction, startJob } from '@/lib/ops';
import { getProjectSetting, projectId } from '@/lib/projects';

export const dynamic = 'force-dynamic';

export async function POST(request: Request) {
  let body: { noteIds?: string[]; projectId?: string } = {};
  try { body = await request.json() as typeof body; } catch { return jsonError('无效的请求体'); }
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, body.projectId, 'write')
    : (await apiUser(true) ? { ok: true, status: 200, error: '', context: { projectId: String(body.projectId || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  try {
    await ensureSchema(); const d1 = db();
    const acceptance=await getProjectSetting(project,'acceptance',{supplierSimilarity:.58}); const threshold=Math.min(1,Math.max(.3,Number(acceptance.supplierSimilarity||.58)));
    const selected = (body.noteIds || []).filter(Boolean).slice(0, 40);
    const summary = { exact: 0, modified: 0, missing: 0, failedNotes: 0 };
    let totalProcessed = 0;
    const MAX_BATCHES = 5;
    let batch = 0;
    const jobId = await startJob('supplier_verify', '核验供应商评论', 0, project);
    const startTime = Date.now();
    const TIME_BUDGET_MS = 25000;
    const commentCache = new Map<string, Array<{ content: string }>>();

    while (batch < MAX_BATCHES) {
      if (batch > 0 && Date.now() - startTime > TIME_BUDGET_MS) break;
      batch++;
      const rows = selected.length && batch === 1
        ? await d1.prepare(`SELECT id,note_id AS noteId,planned_content AS plannedContent FROM supplier_comments WHERE project_id=? AND note_id IN (${selected.map(() => '?').join(',')})`).bind(project,...selected).all<{ id: number; noteId: string; plannedContent: string }>()
        : await d1.prepare("SELECT id,note_id AS noteId,planned_content AS plannedContent FROM supplier_comments WHERE project_id=? AND visibility='待核验' LIMIT 300").bind(project).all<{ id: number; noteId: string; plannedContent: string }>();

      if (!rows.results || rows.results.length === 0) break;

      const grouped = new Map<string, typeof rows.results>();
      for (const row of rows.results) grouped.set(row.noteId, [...(grouped.get(row.noteId) || []), row]);

      for (const [noteId, planned] of grouped) {
        if (Date.now() - startTime > TIME_BUDGET_MS) break;
        let comments: Array<{ content: string }> = commentCache.get(noteId) || [];
        if (!commentCache.has(noteId)) {
          const localKc = await d1.prepare('SELECT content FROM key_comments WHERE project_id=? AND note_id=?').bind(project, noteId).all<{ content: string }>().catch(() => ({ results: [] }));
          if (localKc.results && localKc.results.length > 0) {
            comments = localKc.results;
          } else {
            try {
              const live = await fetchAllComments(noteId, project);
              comments = live.comments || [];
            } catch {
              summary.failedNotes += 1;
            }
          }
          commentCache.set(noteId, comments);
        }

        const now = new Date().toISOString();
        const updateStmts = [];
        for (const row of planned) {
          let best = { score: 0, content: '' };
          for (const comment of comments) {
            const score = similarity(row.plannedContent, comment.content);
            if (score > best.score) best = { score, content: comment.content };
          }
          const visibility = best.score === 1 ? '当前外显-原文一致' : best.score >= threshold ? '当前外显-有修改' : '当前未外显';
          if (best.score === 1) summary.exact += 1;
          else if (best.score >= threshold) summary.modified += 1;
          else summary.missing += 1;
          updateStmts.push(d1.prepare('UPDATE supplier_comments SET visibility=?,matched_content=?,verified_at=? WHERE id=?')
            .bind(visibility, best.score >= threshold ? best.content : null, now, row.id));
          totalProcessed++;
        }
        if (updateStmts.length > 0) {
          await d1.batch(updateStmts);
        }
      }

      if (selected.length > 0) break;
    }

    const remainingRow = await d1.prepare("SELECT COUNT(*) AS count FROM supplier_comments WHERE project_id=? AND visibility='待核验'").bind(project).first<{ count: number }>();
    const remaining = Number(remainingRow?.count || 0);

    await finishJob(jobId, { succeeded: summary.exact + summary.modified + summary.missing, failed: summary.failedNotes, message: `外显 ${summary.exact + summary.modified}，未外显 ${summary.missing}，剩余待核验 ${remaining}` });
    await logAction('供应商外显核验','supplier','',`原文 ${summary.exact}，修改 ${summary.modified}，未外显 ${summary.missing}`,project);
    return Response.json({ ok: true, summary, processed: totalProcessed, remaining, failedNotes: summary.failedNotes, jobId });
  } catch (error) { return jsonError(error instanceof Error ? error.message : '核验失败', 500); }
}

import React, { useState, useEffect, useRef } from 'react';
import type { Note, NoteDetail } from '../../lib/types/project';
import { api, cnTime, pct } from '../../lib/hooks/use-project-data';

export type NoteDetailContext = 'content' | 'comments' | 'acceptance' | 'growth' | 'insights';

export function NoteDetailDrawer({
  detail,
  close,
  saveNote,
  removeNote,
  context = 'content',
  defaultTab,
  projectId,
  onRefresh,
  baseCount = 30,
}: {
  detail: NoteDetail;
  close: () => void;
  saveNote?: (note: Note) => void;
  removeNote?: (note: Note) => void;
  context?: NoteDetailContext;
  defaultTab?: 'basic' | 'performance' | 'comments' | 'acceptance';
  projectId?: string;
  onRefresh?: (opts?: { fresh?: boolean }) => Promise<void>;
  baseCount?: number;
}) {
  const n = detail.note;
  const [draft, setDraft] = useState(n);
  const [calibrating, setCalibrating] = useState(false);
  const [calibrationReason, setCalibrationReason] = useState('');
  const [calibrationSuccess, setCalibrationSuccess] = useState('');
  const drawerRef = useRef<HTMLElement>(null);
  const triggerElementRef = useRef<HTMLElement | null>(null);

  const initialTab = defaultTab || (
    context === 'comments' || context === 'acceptance' ? 'comments' :
    context === 'insights' ? 'performance' :
    'basic'
  );
  const [tab, setTab] = useState<'basic' | 'performance' | 'comments' | 'acceptance'>(initialTab);

  const allowEditStatus = context === 'acceptance';

  useEffect(() => {
    triggerElementRef.current = document.activeElement as HTMLElement | null;
    drawerRef.current?.focus();
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        close();
        return;
      }
      if (e.key === 'Tab' && drawerRef.current) {
        const focusables = drawerRef.current.querySelectorAll<HTMLElement>(
          'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
        );
        if (!focusables.length) return;
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      triggerElementRef.current?.focus();
    };
  }, [close]);

  async function handleCalibrateAcceptance() {
    if (!draft?.id || !draft.status) return;
    setCalibrating(true);
    setCalibrationSuccess('');
    try {
      await api('/api/resources', {
        method: 'POST',
        body: JSON.stringify({
          action: 'calibrate_acceptance',
          projectId,
          noteId: draft.id,
          newStatus: draft.status,
          reason: calibrationReason || '人工验收校正',
        }),
      });
      setCalibrationSuccess('验收状态已校正并记入审计日志');
      if (onRefresh) await onRefresh({ fresh: true });
    } catch (e) {
      alert(e instanceof Error ? e.message : '校正失败');
    } finally {
      setCalibrating(false);
    }
  }

  return (
    <div className="drawer-backdrop" onMouseDown={close}>
      <aside
        ref={drawerRef}
        tabIndex={-1}
        className="drawer"
        onMouseDown={(e) => e.stopPropagation()}
        style={{ width: '520px', maxWidth: '92vw', outline: 'none' }}
      >
        <button type="button" className="drawer-close" onClick={close} aria-label="关闭抽屉">
          ×
        </button>
        <small style={{ color: '#0284c7', fontWeight: 700 }}>NOTE DETAIL</small>
       <h2 style={{ fontSize: '18px', marginTop: '4px', marginBottom: '8px' }}>{n?.title || n?.id || '笔记明细'}</h2>
       <p className="drawer-meta" style={{ fontSize: '12.5px', color: '#64748b' }}>
         {n?.author || '未知博主'} · {n?.status || '待抓取'} · 最近抓取 {cnTime(n?.lastFetchedAt)}
       </p>

        {/* 笔记封面与正文内容速览 */}
        <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '10px', padding: '12px', display: 'flex', gap: '14px', alignItems: 'flex-start' }}>
          {n?.coverUrl ? (
            <img
              src={n.coverUrl}
              alt=""
              style={{ width: '84px', height: '112px', objectFit: 'cover', borderRadius: '6px', border: '1px solid #cbd5e1', flexShrink: 0 }}
              loading="lazy"
              onError={(e) => {
                e.currentTarget.onerror = null;
                e.currentTarget.src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="84" height="112" viewBox="0 0 24 24" fill="none" stroke="%2394a3b8" stroke-width="1.5"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="m3 15 5-5c.9-.9 2.1-.9 3 0l7 7"/><circle cx="8.5" cy="8.5" r="1.5"/></svg>';
              }}
            />
          ) : (
            <div style={{ width: '84px', height: '112px', background: '#e2e8f0', color: '#64748b', borderRadius: '6px', display: 'grid', placeItems: 'center', fontSize: '24px', fontWeight: 700, flexShrink: 0 }}>
              {(n?.author || '笔').slice(0, 1)}
            </div>
          )}
          <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: '6px' }}>
            <div style={{ fontSize: '12px', color: '#475569', fontWeight: 600 }}>
              笔记正文与切角：
            </div>
            <div style={{ fontSize: '12.5px', color: '#1e293b', lineHeight: 1.5, maxHeight: '72px', overflowY: 'auto', background: '#ffffff', border: '1px solid #f1f5f9', borderRadius: '6px', padding: '6px 8px' }}>
              {n?.content ? n.content : n?.title ? `【${n.title}】${n.category1 ? ` · 切角：${n.category1}` : ''} · ${n.category2 ? `场景：${n.category2}` : ''}` : '笔记正文由蒲公英/小红书抓取同步，当前尚未提取正文长文本。'}
            </div>
            {n?.url && (
              <a
                href={n.url}
                target="_blank"
                rel="noreferrer"
                className="text-link"
                style={{ fontSize: '12px', color: '#0284c7', alignSelf: 'flex-start', fontWeight: 500 }}
              >
                在小红书前台查看原笔记 ↗
              </a>
            )}
          </div>
        </div>

       <nav className="ops-drawer-tabs" role="tablist" aria-label="明细标签">
          <button
            type="button"
            role="tab"
            aria-selected={tab === 'basic'}
            className={`ops-drawer-tab ${tab === 'basic' ? 'active' : ''}`}
            onClick={() => setTab('basic')}
          >
            基础资料
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={tab === 'performance'}
            className={`ops-drawer-tab ${tab === 'performance' ? 'active' : ''}`}
            onClick={() => setTab('performance')}
          >
            内容表现
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={tab === 'comments'}
            className={`ops-drawer-tab ${tab === 'comments' ? 'active' : ''}`}
            onClick={() => setTab('comments')}
          >
            评论监测
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={tab === 'acceptance'}
            className={`ops-drawer-tab ${tab === 'acceptance' ? 'active' : ''}`}
            onClick={() => setTab('acceptance')}
          >
            验收与处置
          </button>
        </nav>

       {tab === 'basic' && (
         <div className="drawer-tab-content" role="tabpanel" aria-label="基础资料">
           {draft && (
             <section className="note-editor">
                {context === 'comments' || context === 'acceptance' ? (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                    <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '12px' }}>
                      <span style={{ fontSize: '11px', color: '#64748b', fontWeight: 600 }}>笔记标题</span>
                      <div style={{ fontSize: '13.5px', color: '#0f172a', fontWeight: 600, marginTop: '2px' }}>{draft.title || '未命名笔记'}</div>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                      <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '10px 12px' }}>
                        <span style={{ fontSize: '11px', color: '#64748b', fontWeight: 600 }}>作者 / 博主</span>
                        <div style={{ fontSize: '13px', color: '#1e293b', marginTop: '2px' }}>{draft.author || '未知博主'}</div>
                      </div>
                      <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '10px 12px' }}>
                        <span style={{ fontSize: '11px', color: '#64748b', fontWeight: 600 }}>产品范围</span>
                        <div style={{ fontSize: '13px', color: '#1e293b', marginTop: '2px' }}>{draft.productScope || '本品'}</div>
                      </div>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                      <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '10px 12px' }}>
                        <span style={{ fontSize: '11px', color: '#64748b', fontWeight: 600 }}>来源分类</span>
                        <div style={{ fontSize: '13px', color: '#1e293b', marginTop: '2px' }}>
                          {draft.sourceType === 'owned' ? '自有发布' : draft.sourceType === 'commercial' ? '商业合作' : '关键词扫描'}
                        </div>
                      </div>
                      <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '10px 12px' }}>
                        <span style={{ fontSize: '11px', color: '#64748b', fontWeight: 600 }}>验收状态</span>
                        <div style={{ fontSize: '13px', color: '#1e293b', fontWeight: 600, marginTop: '2px' }}>{draft.status || '待抓取'}</div>
                      </div>
                    </div>
                    {draft.url && (
                      <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '10px 12px' }}>
                        <span style={{ fontSize: '11px', color: '#64748b', fontWeight: 600 }}>笔记链接</span>
                        <div style={{ marginTop: '2px', wordBreak: 'break-all' }}>
                          <a href={draft.url} target="_blank" rel="noreferrer" className="text-link" style={{ fontSize: '12.5px' }}>
                            {draft.url} ↗
                          </a>
                        </div>
                      </div>
                    )}
                    <div style={{ fontSize: '12px', color: '#64748b', background: '#f1f5f9', padding: '8px 12px', borderRadius: '6px' }}>
                      ℹ️ 评论运营与验收模式下基础资料为只读锁定状态；如需调整状态请前往“验收与处置”标签进行校正。
                    </div>
                  </div>
                ) : (
                  <>
                <label>
                  标题
                  <input
                    value={draft.title || ''}
                    onChange={(e) => setDraft({ ...draft, title: e.target.value })}
                  />
                </label>
                <label>
                  博主
                  <input
                    value={draft.author || ''}
                    onChange={(e) => setDraft({ ...draft, author: e.target.value })}
                  />
                </label>
                <label>
                  笔记链接
                  <input
                    value={draft.url || ''}
                    onChange={(e) => setDraft({ ...draft, url: e.target.value })}
                  />
                </label>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                  <label>
                    来源分类
                    <select
                      value={draft.sourceType || 'scan'}
                      onChange={(e) => setDraft({ ...draft, sourceType: e.target.value })}
                    >
                      <option value="owned">自有发布</option>
                      <option value="commercial">商业合作</option>
                      <option value="keyword_scan">关键词扫描</option>
                    </select>
                  </label>
                  <label>
                    产品范围
                    <select
                      value={draft.productScope || '本品'}
                      onChange={(e) => setDraft({ ...draft, productScope: e.target.value })}
                    >
                      <option value="本品">本品</option>
                      <option value="竞品">竞品</option>
                      <option value="其他">其他</option>
                    </select>
                  </label>
                </div>

                <div style={{ fontSize: '12px', color: '#64748b', margin: '4px 0 8px' }}>
                  验收状态：<strong>{draft.status || '待抓取'}</strong>（校正请前往“验收与处置”标签）
                </div>

                <div style={{ display: 'flex', gap: '8px', marginTop: '16px' }}>
                  {saveNote && (
                    <button type="button" className="primary" onClick={() => saveNote(draft)}>
                      保存基础资料
                    </button>
                  )}
                  {removeNote && (
                    <button type="button" className="danger-link" onClick={() => removeNote(draft)}>
                      移出项目
                    </button>
                  )}
                </div>
                  </>
                )}
              </section>
            )}
          </div>
        )}

        {tab === 'performance' && (
          <div className="drawer-tab-content" role="tabpanel" aria-label="内容表现">
            <section className="mini-kpis">
              <article>
                <p>阅读量</p>
                <strong>{n?.readCount ? Number(n.readCount).toLocaleString() : '—'}</strong>
                <span className="up">单篇总阅读</span>
              </article>
              <article>
                <p>互动量</p>
                <strong>{n?.interactionCount ? Number(n.interactionCount).toLocaleString() : '—'}</strong>
                <span className="up">赞藏评总计</span>
              </article>
              <article>
                <p>互动率</p>
                <strong>
                  {n?.readCount && n?.interactionCount
                    ? pct(Number(n.interactionCount) / Number(n.readCount))
                    : '—'}
                </strong>
                <span className="up">互动/阅读</span>
              </article>
            </section>

            <div style={{ marginTop: '16px', fontSize: '13px', display: 'grid', gap: '8px' }}>
              <div><strong>内容方向：</strong>{n?.category1 || '待补充'}</div>
              <div><strong>内容形式：</strong>{n?.noteType || '待补充'}</div>
              <div><strong>达人层级：</strong>{n?.creatorLevel || '待补充'}</div>
              <div><strong>点赞数：</strong>{n?.likeCount ?? '—'}</div>
              <div><strong>收藏数：</strong>{n?.favoriteCount ?? '—'}</div>
            </div>
          </div>
        )}

        {tab === 'comments' && (
          <div className="drawer-tab-content" role="tabpanel" aria-label="评论监测">
            <section className="mini-kpis">
              <article>
                <p>评论总数</p>
                <strong>{n?.commentTotal || 0}</strong>
                <span className="up">主评+楼中楼</span>
              </article>
              <article>
                <p>正向评论</p>
                <strong>{n?.positiveCount || 0}</strong>
                <span className="up">
                  {n?.commentTotal ? pct((n.positiveCount || 0) / n.commentTotal) : '—'}
                </span>
              </article>
              <article>
                <p>负向/问询</p>
                <strong>{(n?.negativeCount || 0) + (n?.questionCount || 0)}</strong>
                <span className="danger">重点复查</span>
              </article>
            </section>

            <h3 style={{ fontSize: '14px', marginTop: '16px', marginBottom: '8px' }}>抓取指标快照</h3>
            <div className="snapshot-list">
              {detail.snapshots && detail.snapshots.length ? (
                detail.snapshots.map((x) => (
                  <div key={x.capturedAt}>
                    <time>{cnTime(x.capturedAt)}</time>
                    <span>主评 {x.l1Count}</span>
                    <span>楼中楼 {x.l2Count}</span>
                    <b>合计 {x.totalCount}</b>
                  </div>
                ))
              ) : (
                <div className="empty">暂无历史快照</div>
              )}
            </div>
          </div>
        )}

        {tab === 'acceptance' && (
          <div className="drawer-tab-content" role="tabpanel" aria-label="验收与处置">
            <div style={{ marginBottom: '16px', padding: '12px', background: '#f8fafc', borderRadius: '8px', fontSize: '13px' }}>
              <div><strong>当前验收状态：</strong>{n?.status || '待抓取'}</div>
              <div><strong>前5主评品牌提及率：</strong>{pct(n?.brandMentionTop5 || 0)}</div>
            </div>

            {allowEditStatus && (
              <div style={{ margin: '16px 0', padding: '14px', background: '#f0fdf4', borderRadius: '8px', border: '1px solid #bbf7d0' }}>
                <strong style={{ fontSize: '13.5px', color: '#166534' }}>人工验收校正（独立审计归档）</strong>
                <div style={{ display: 'grid', gap: '8px', marginTop: '8px' }}>
                  <label style={{ fontSize: '12px', color: '#15803d' }}>
                    校正验收结果
                    <select
                      value={draft?.status || '待抓取'}
                      onChange={(e) => setDraft((prev) => (prev ? { ...prev, status: e.target.value } : prev))}
                    >
                      <option value="待抓取">待抓取</option>
                      <option value="符合基础要求">符合基础要求</option>
                      <option value="符合且能汇报">符合且能汇报</option>
                      <option value={`不够${baseCount}条需补充`}>不够{baseCount}条需补充</option>
                    </select>
                  </label>
                  <label style={{ fontSize: '12px', color: '#15803d' }}>
                    校正原因说明
                    <input
                      placeholder="例如：人工复核前5条主评品牌提及达标"
                      value={calibrationReason}
                      onChange={(e) => setCalibrationReason(e.target.value)}
                    />
                  </label>
                  <button
                    type="button"
                    className="primary"
                    disabled={calibrating}
                    style={{ background: '#16a34a', borderColor: '#15803d', fontSize: '12.5px', padding: '6px 12px' }}
                    onClick={handleCalibrateAcceptance}
                  >
                    {calibrating ? '校正提交中…' : '提交人工验收校正'}
                  </button>
                  {calibrationSuccess && (
                    <span style={{ fontSize: '12px', color: '#15803d' }}>✓ {calibrationSuccess}</span>
                  )}
                </div>
              </div>
            )}

            <h3 style={{ fontSize: '14px', marginBottom: '8px' }}>需处置关键评论</h3>
            <div className="drawer-comments">
              {detail.comments && detail.comments.length ? (
                detail.comments.map((x) => (
                  <article key={x.id}>
                    <span>{x.sentiment} · {x.category}</span>
                    <p>{x.content}</p>
                    <small>{x.action} · {x.treatmentStatus}</small>
                  </article>
                ))
              ) : (
                <div className="empty">暂无需处置的关键评论</div>
              )}
            </div>
          </div>
        )}
      </aside>
    </div>
  );
}

