export function useCategoryNotesModal({
  projectId,
}: {
  projectId?: string;
} = {}) {
  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    title: string;
    subtitle?: string;
    tag?: string;
    notes: Note[];
    maxCount?: number;
  }>({
    isOpen: false,
    title: '',
    subtitle: '',
    tag: '分类笔记',
    notes: [],
    maxCount: 50,
  });

  const openCategoryNotes = (options: {
    title: string;
    subtitle?: string;
    tag?: string;
    notes: Note[];
    maxCount?: number;
  }) => {
    setModalState({
      isOpen: true,
      title: options.title,
      subtitle: options.subtitle,
      tag: options.tag || '分类笔记',
      notes: options.notes || [],
      maxCount: options.maxCount || 50,
    });
  };

  const closeCategoryNotes = () => {
    setModalState((prev) => ({ ...prev, isOpen: false }));
  };

  const renderCategoryNotesModal = () => (
    <CategoryNotesModal
      isOpen={modalState.isOpen}
      title={modalState.title}
      subtitle={modalState.subtitle}
      tag={modalState.tag}
      notes={modalState.notes}
      maxCount={modalState.maxCount}
      projectId={projectId}
      onClose={closeCategoryNotes}
    />
  );

  return {
    modalState,
    openCategoryNotes,
    closeCategoryNotes,
    renderCategoryNotesModal,
  };
}

