'use client';

import React, { useEffect, useState } from 'react';

const PASTEL_PALETTES = [
  { bg: 'linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%)', text: '#0369a1', border: '#7dd3fc' },
  { bg: 'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)', text: '#15803d', border: '#86efac' },
  { bg: 'linear-gradient(135deg, #f3e8ff 0%, #e9d5ff 100%)', text: '#7e22ce', border: '#d8b4fe' },
  { bg: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)', text: '#b45309', border: '#fcd34d' },
  { bg: 'linear-gradient(135deg, #ffe4e6 0%, #fecdd3 100%)', text: '#be123c', border: '#fda4af' },
  { bg: 'linear-gradient(135deg, #ccfbf1 0%, #99f6e4 100%)', text: '#0f766e', border: '#5eead4' },
];

function hashColor(str: string) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return PASTEL_PALETTES[Math.abs(hash) % PASTEL_PALETTES.length];
}

export function NoteThumbnail({
  src,
  alt = '',
  title = '',
  author = '',
  category = '笔记',
  className = 'ops-table-note-cover',
  eager = false,
}: {
  src?: string | null;
  alt?: string;
  title?: string;
  author?: string;
  category?: string;
  className?: string;
  eager?: boolean;
}) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  const [resolved, setResolved] = useState<{ key: string; url: string } | null>(null);
  const needsResolve = Boolean(src?.startsWith('/api/note-covers?resolve=1&'));
  useEffect(() => {
    if (!needsResolve || !src) return;
    const controller = new AbortController();
    let retryTimer: ReturnType<typeof setTimeout> | undefined;
    const load = async (attempt = 0) => {
      try {
        const response = await fetch(src + '&format=json', { signal: controller.signal });
        if (!response.ok) throw new Error('封面暂不可用');
        const data = await response.json() as { coverUrl?: string };
        if (!data.coverUrl?.startsWith('https://')) throw new Error('无有效封面');
        if (!controller.signal.aborted) setResolved({ key: src, url: data.coverUrl });
      } catch {
        if (!controller.signal.aborted && attempt < 2) retryTimer = setTimeout(() => void load(attempt + 1), 1500 * (attempt + 1));
      }
    };
    // Resolve metadata on mount: restored/background tabs can defer intersection
    // callbacks indefinitely. The image itself still uses native lazy loading.
    void load();
    return () => { controller.abort(); clearTimeout(retryTimer); };
  }, [src, needsResolve]);
  const cleanSrc = needsResolve ? (resolved && resolved.key === src ? resolved.url : '') : src && (/^https?:\/\//.test(src) || src.startsWith('/api/note-covers?')) ? src : '';
  const palette = hashColor(author || title || category);
  const initial = (author || title || category || '笔').trim().slice(0, 1);

  if (!cleanSrc || failedSrc === cleanSrc) {
    return (
      <div
        className={className}
        style={{
          background: palette.bg,
          border: `1px solid ${palette.border}`,
          color: palette.text,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          fontWeight: 700,
          fontSize: className.includes('table') ? '13px' : '22px',
          userSelect: 'none',
          position: 'relative',
          overflow: 'hidden',
        }}
        title={`${title || author} · 暂无可用封面`}
      >
        <span>{initial}</span>
        {className.includes('card') && (
          <span
            style={{
              position: 'absolute',
              bottom: 6,
              fontSize: '10px',
              padding: '1px 6px',
              background: 'rgba(255,255,255,0.7)',
              borderRadius: '4px',
              fontWeight: 600,
              color: palette.text,
            }}
          >
            {category}
          </span>
        )}
      </div>
    );
  }

  return (
    <img
      src={cleanSrc}
      alt={alt || title}
      className={className}
      loading={eager ? 'eager' : 'lazy'}
      decoding="async"
      referrerPolicy="no-referrer"
      onError={() => setFailedSrc(cleanSrc)}
    />
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from '../../components/ui/AppLink';
import { MetricCard } from '../../components/ui/operations/MetricCard';
import { DashboardSection } from '../../components/ui/operations/DashboardSection';
import { StatusBadge } from '../../components/ui/operations/StatusBadge';
import { ProgressBar } from '../../components/ui/operations/ProgressBar';
import { WorkspaceToolbar } from '../../components/ui/operations/WorkspaceToolbar';
import { DataTableShell } from '../../components/ui/operations/DataTableShell';
import { EmptyState } from '../../components/ui/EmptyState';
import { CustomSelect } from '../../components/ui/CustomSelect';
import { api, cnTime, pct } from '../../lib/hooks/use-project-data';
import type { Dashboard, Acceptance } from '../../lib/types/project';
import { emptyNotesSummary, type NoteListItem, type NotesListResponse } from '../content/content-view-model';

export function AcceptanceDelivery({
  projectId,
  dashboard,
  acceptance,
  openNote,
  openCategoryNotes,
  toast,
}: {
  projectId: string;
  dashboard: Dashboard;
  acceptance: Acceptance;
  openNote: (id: string) => void;
  toast: (msg: string, type?: 'success' | 'error' | 'info') => void;
  openCategoryNotes?: (opts: { title: string; subtitle?: string; tag?: string; notes: any[]; maxCount?: number }) => void;
}) {
  const handlePipelineClick = (pipeName: string) => {
    if (!openCategoryNotes) return;
    const clean = pipeName.trim();
    const matched = (dashboard.notes || []).filter(n => {
      const p = (n.pipeline || '').trim();
      return p === clean || clean.includes(p) || (n.title || '').includes(clean);
    });
    openCategoryNotes({
      title: '投放主线 · ' + clean,
      subtitle: '该主线已收录 ' + matched.length + ' 篇笔记，展示前 50 篇（按互动量降序）',
      tag: '投放主线',
      notes: matched.length ? matched : (dashboard.notes || []).slice(0, 30),
      maxCount: 50,
    });
  };

  const [items, setItems] = useState<NoteListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [summary, setSummary] = useState<NotesListResponse['summary']>(emptyNotesSummary);

  const searchParams = useSearchParams();
  const [query, setQuery] = useState(searchParams.get('query') || '');
  const [statusFilter, setStatusFilter] = useState(searchParams.get('status') || '');
  const [page, setPage] = useState(Math.max(1, parseInt(searchParams.get('page') || '1', 10)));
  const [loading, setLoading] = useState(false);
  // 弹窗状态：展示卡片对应的笔记列表
  const [modalFilter, setModalFilter] = useState<{
    title: string;
    tag: string;
    theme: string;
    status?: string;
    type?: 'replyPending';
  } | null>(null);
  const [modalItems, setModalItems] = useState<NoteListItem[]>([]);
  const [modalLoading, setModalLoading] = useState(false);
  const [modalPage, setModalPage] = useState(1);
  const [modalTotal, setModalTotal] = useState(0);

  const [debouncedQuery, setDebouncedQuery] = useState(query);
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), 300);
    return () => clearTimeout(timer);
  }, [query]);

  const syncToUrl = useCallback((nextState: { query: string; status: string; page: number }) => {
    try {
      const p = new URLSearchParams(window.location.search);
      if (nextState.query) p.set('query', nextState.query); else p.delete('query');
      if (nextState.status) p.set('status', nextState.status); else p.delete('status');
      if (nextState.page > 1) p.set('page', String(nextState.page)); else p.delete('page');
      window.history.replaceState(null, '', window.location.pathname + (p.toString() ? '?' + p.toString() : ''));
    } catch {}
  }, []);

  useEffect(() => {
    syncToUrl({ query: debouncedQuery, status: statusFilter, page });
  }, [debouncedQuery, statusFilter, page, syncToUrl]);

  useEffect(() => {
    const handlePopState = () => {
      const p = new URLSearchParams(window.location.search);
      setQuery(p.get('query') || '');
      setDebouncedQuery(p.get('query') || '');
      setStatusFilter(p.get('status') || '');
      setPage(Math.max(1, parseInt(p.get('page') || '1', 10)));
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadAcceptanceNotes = useCallback(async () => {
    setLoading(true);
    try {
      const p = new URLSearchParams({
        projectId,
        view: 'acceptance',
        page: String(page),
        pageSize: '20',
      });
      if (debouncedQuery) p.set('query', debouncedQuery);
      if (statusFilter) p.set('status', statusFilter);
      const res = await api<NotesListResponse>('/api/notes/list?' + p.toString());
      setItems(res.items || []);
      setTotal(res.total || 0);
      if (res.summary) setSummary(res.summary);
    } catch (e) {
      toast(e instanceof Error ? e.message : '加载验收明细失败', 'error');
    } finally {
      setLoading(false);
    }
  }, [projectId, page, debouncedQuery, statusFilter, toast]);

  useEffect(() => {
    const timer = setTimeout(() => {
      void loadAcceptanceNotes();
    }, 0);
    return () => clearTimeout(timer);
  }, [loadAcceptanceNotes]);

  // Page/loading changes originate in selection and pagination events.
  // This effect only subscribes to the response for the selected page.
  useEffect(() => {
    if (!modalFilter) return;
    const controller = new AbortController();
    const p = new URLSearchParams({ projectId, view: 'acceptance', page: String(modalPage), pageSize: '12' });
    if (modalFilter.status) p.set('status', modalFilter.status);
    if (modalFilter.type === 'replyPending') p.set('replyPending', '1');
    void api<NotesListResponse>('/api/notes/list?' + p.toString(), { signal: controller.signal })
      .then(res => {
        if (controller.signal.aborted) return;
        setModalItems(res.items || []);
        setModalTotal(res.total || 0);
      })
      .catch(e => {
        if (controller.signal.aborted) return;
        setModalItems([]);
        setModalTotal(0);
        toast(e instanceof Error ? e.message : '加载笔记列表失败', 'error');
      })
      .finally(() => { if (!controller.signal.aborted) setModalLoading(false); });
    return () => controller.abort();
  }, [projectId, modalFilter, modalPage, toast]);

  const reportReq = acceptance.reportCount || 200;
  const baseReq = acceptance.baseCount || 30;
  const brandReqRate = acceptance.brandTopRate || 0.4;

  return (
    <div className="stack animate-fade-in">
      {/* 顶部真实经营 KPI */}
      <section className="ops-metric-grid">
        <MetricCard
          theme="green"
          label="符合且能汇报"
          value={summary.reportableCount.toLocaleString()}
          unit="篇"
          desc={`≥${reportReq}条评论 且 前5提及率≥${pct(brandReqRate)}`}
          tag="最高档交付"
          clickable
          onClick={() => { setModalLoading(true); setModalPage(1); setModalFilter({ title: '符合且能汇报的笔记', tag: '最高档交付', theme: 'green', status: '符合且能汇报' }); }}
        />
        <MetricCard
          theme="blue"
          label="符合基础要求"
          value={summary.baseCount.toLocaleString()}
          unit="篇"
          desc={`有效评论达到 ${baseReq} 条考核基线`}
