// ======================== Client Cache for Workbench ========================
type WorkbenchCacheData = {
  items: ActionWorkbenchItem[];
  total: number;
  summary: {
    totalPending: number;
    replyPending: number;
    deletePending: number;
    supplementPending: number;
    observePending: number;
    handledCount: number;
  };
  availableDates: string[];
  needsRecalculation: boolean;
  timestamp: number;
};
const workbenchCache = new Map<string, WorkbenchCacheData>();
const CACHE_FRESH_MS = 60 * 1000;
function getCache(key: string): WorkbenchCacheData | null {
  const mem = workbenchCache.get(key);
  if (mem) return mem;
  if (typeof window === 'undefined') return null;
  try {
    const raw = sessionStorage.getItem('wb_cache:' + key);
    if (raw) {
      const parsed = JSON.parse(raw) as WorkbenchCacheData;
      workbenchCache.set(key, parsed);
      return parsed;
    }
  } catch {}
  return null;
}
function setCache(key: string, data: Omit<WorkbenchCacheData, 'timestamp'>) {
  const entry = { ...data, timestamp: Date.now() };
  workbenchCache.set(key, entry);
  if (typeof window !== 'undefined') {
    try {
      sessionStorage.setItem('wb_cache:' + key, JSON.stringify(entry));
    } catch {}
  }
}

export function CommentActionWorkbench({
  projectId,
  openNote,
  onRefresh,
  toast,
}: {
  projectId: string;
  openNote?: (id: string) => void;
  onRefresh: (opts?: { fresh?: boolean }) => Promise<void>;
  toast: (msg: string, type?: 'success' | 'error' | 'info') => void;
}) {
  const searchParams = useSearchParams();

  // Initialize from URL search params
  const [sourceFilter, setSourceFilter] = useState<'all' | 'key-comment' | 'review-batch'>(
    (searchParams.get('source') as 'all' | 'key-comment' | 'review-batch') || 'all'
  );
  const [actionFilter, setActionFilter] = useState(searchParams.get('action') || '');
  const [statusFilter, setStatusFilter] = useState(searchParams.get('status') || 'pending');
  const [sentimentFilter, setSentimentFilter] = useState(searchParams.get('sentiment') || '');
  const [categoryFilter, setCategoryFilter] = useState(searchParams.get('category') || '');
  const [selectedDate, setSelectedDate] = useState<string>(searchParams.get('date') || '');
  const [query, setQuery] = useState(searchParams.get('query') || '');
  const [page, setPage] = useState(Math.max(1, parseInt(searchParams.get('page') || '1', 10)));

  const [loading, setLoading] = useState(false);
  const [summaryReady, setSummaryReady] = useState(false);
  const [needsRecalculation, setNeedsRecalculation] = useState(false);
  const [recalculating, setRecalculating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<ActionWorkbenchItem[]>([]);
  const [total, setTotal] = useState(0);
  const [availableDates, setAvailableDates] = useState<string[]>([]);
  const [summary, setSummary] = useState({
    totalPending: 0,
    replyPending: 0,
    deletePending: 0,
    supplementPending: 0,
    observePending: 0,
    handledCount: 0,
  });

  const reqSeqRef = useRef(0);
  const resultsRef = useRef<HTMLDivElement>(null);
  const scrollAfterLoadRef = useRef(false);
  const [resultFocusRequest, setResultFocusRequest] = useState(0);

  useEffect(() => {
    if (loading || !scrollAfterLoadRef.current) return;
    const frame = requestAnimationFrame(() => {
      resultsRef.current?.scrollIntoView({ behavior: 'auto', block: 'start' });
      resultsRef.current?.focus({ preventScroll: true });
      scrollAfterLoadRef.current = false;
    });
    return () => cancelAnimationFrame(frame);
  }, [loading, items, error, resultFocusRequest]);

  // Sync state to URL with replaceState
  const syncToUrl = useCallback(
    (nextState: {
      query: string;
      source: string;
      status: string;
      action: string;
      sentiment: string;
      category: string;
      date: string;
      page: number;
    }) => {
      try {
        const p = new URLSearchParams(window.location.search);
        if (nextState.query) p.set('query', nextState.query); else p.delete('query');
        if (nextState.source && nextState.source !== 'all') p.set('source', nextState.source); else p.delete('source');
        if (nextState.status && nextState.status !== 'pending') p.set('status', nextState.status); else p.delete('status');
        if (nextState.action) p.set('action', nextState.action); else p.delete('action');
        if (nextState.sentiment) p.set('sentiment', nextState.sentiment); else p.delete('sentiment');
        if (nextState.category) p.set('category', nextState.category); else p.delete('category');
        if (nextState.date) p.set('date', nextState.date); else p.delete('date');
        if (nextState.page > 1) p.set('page', String(nextState.page)); else p.delete('page');
        window.history.replaceState(null, '', window.location.pathname + (p.toString() ? '?' + p.toString() : ''));
      } catch {}
    },
    []
  );

  // Debounce query and trigger search
  const [debouncedQuery, setDebouncedQuery] = useState(query);
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(query);
    }, 300);
    return () => clearTimeout(timer);
  }, [query]);

  // Sync state changes to URL
  useEffect(() => {
    syncToUrl({
      query: debouncedQuery,
      source: sourceFilter,
      status: statusFilter,
      action: actionFilter,
      sentiment: sentimentFilter,
      category: categoryFilter,
      date: selectedDate,
      page,
    });
  }, [debouncedQuery, sourceFilter, statusFilter, actionFilter, sentimentFilter, categoryFilter, selectedDate, page, syncToUrl]);

  // Handle browser Back/Forward (popstate)
  useEffect(() => {
    const handlePopState = () => {
      const p = new URLSearchParams(window.location.search);
      setQuery(p.get('query') || '');
      setDebouncedQuery(p.get('query') || '');
      setSourceFilter((p.get('source') as 'all' | 'key-comment' | 'review-batch') || 'all');
      setStatusFilter(p.get('status') || 'pending');
      setActionFilter(p.get('action') || '');
      setSentimentFilter(p.get('sentiment') || '');
      setCategoryFilter(p.get('category') || '');
      setSelectedDate(p.get('date') || '');
      setPage(Math.max(1, parseInt(p.get('page') || '1', 10)));
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // Server-side paginated data loader
  const loadWorkbenchData = useCallback(async () => {
    const seq = ++reqSeqRef.current;
    const currentCacheKey = [projectId, sourceFilter, statusFilter, actionFilter, sentimentFilter, categoryFilter, selectedDate, debouncedQuery, page].join(":");
    const cached = getCache(currentCacheKey);
    if (cached) {
      setItems(cached.items);
      setTotal(cached.total);
      setSummary(cached.summary);
      setSummaryReady(true);
      setAvailableDates(cached.availableDates);
      setNeedsRecalculation(cached.needsRecalculation);
      if (Date.now() - cached.timestamp < CACHE_FRESH_MS) {
        setLoading(false);
      }
    } else {
      setLoading(true);
    }
    setError(null);
    try {
      const p = new URLSearchParams({
        projectId,
        page: String(page),
        pageSize: '20',
        source: sourceFilter,
        status: statusFilter || 'all',
      });
      if (actionFilter) p.set('action', actionFilter);
      if (sentimentFilter) p.set('sentiment', sentimentFilter);
      if (categoryFilter) p.set('category', categoryFilter);
      if (selectedDate) p.set('date', selectedDate);
      if (debouncedQuery) p.set('query', debouncedQuery);

      const res = await api<{
        ok: boolean;
        items: ActionWorkbenchItem[];
        total: number;
        page: number;
        pageSize: number;
        summary: {
          totalPending: number;
          replyPending: number;
          deletePending: number;
          supplementPending: number;
          observePending: number;
          handledCount: number;
        };
        availableDates: string[];
        needsRecalculation?: boolean;
      }>('/api/actions/workbench?' + p.toString());

      if (seq !== reqSeqRef.current) return;

      const finalItems = res.items || [];
      const finalTotal = res.total || 0;
      const finalRecalc = Boolean(res.needsRecalculation);
      const finalSummary = res.summary || summary;
      const finalDates = res.availableDates || availableDates;
      setItems(finalItems);
      setSummaryReady(true);
      setTotal(finalTotal);
      setNeedsRecalculation(finalRecalc);
      if (res.summary) setSummary(res.summary);
      setCache(currentCacheKey, { items: finalItems, total: finalTotal, summary: finalSummary, availableDates: finalDates, needsRecalculation: finalRecalc });
      if (res.availableDates) {
        setAvailableDates(res.availableDates);
        if (!selectedDate && res.availableDates.length > 0 && sourceFilter === 'review-batch') {
          setSelectedDate(res.availableDates[res.availableDates.length - 1]);
        }
      }
    } catch (e) {
      if (seq !== reqSeqRef.current) return;
      const msg = e instanceof Error ? e.message : '加载待办任务失败';
      setError(msg);
      toast(msg, 'error');
    } finally {
      if (seq === reqSeqRef.current) {
        setLoading(false);
      }
    }
  }, [projectId, page, sourceFilter, statusFilter, actionFilter, sentimentFilter, categoryFilter, selectedDate, debouncedQuery, toast]);

  useEffect(() => {
    const timer = setTimeout(() => { void loadWorkbenchData(); }, 0);
    return () => {
      clearTimeout(timer);
      reqSeqRef.current += 1;
    };
  }, [loadWorkbenchData, resultFocusRequest]);

  // Action handlers with optimistic updates
  async function handleRecalculate() {
    if (!selectedDate) return;
    setRecalculating(true);
    try {
      await api('/api/actions/workbench', {
        method: 'POST',
        body: JSON.stringify({ action: 'recalculate', projectId, date: selectedDate }),
      });
      toast(`已生成 ${selectedDate} 规则判定批次`, 'success');
      setNeedsRecalculation(false);
      await loadWorkbenchData();
      await onRefresh({ fresh: true });
    } catch (err) {
      toast(err instanceof Error ? err.message : '生成判定失败', 'error');
    } finally {
      setRecalculating(false);
    }
  }

  async function handleResolve(item: ActionWorkbenchItem, method: string) {
    try {
      await api('/api/actions/workbench', {
        method: 'POST',
        body: JSON.stringify({
          id: item.id,
          rawId: item.rawId,
          source: item.source,
          action: 'resolve',
          method,
          projectId,
        }),
      });

      // Optimistic update: if in pending view, immediately remove from list
      if (statusFilter === 'pending') {
        setItems((prev) => prev.filter((x) => x.id !== item.id));
        setTotal((prev) => Math.max(0, prev - 1));
      } else {
        setItems((prev) =>
          prev.map((x) => (x.id === item.id ? { ...x, status: 'handled' } : x))
        );
      }
      // A record can match several summary actions. Reload authoritative counts
      // instead of subtracting one action and inventing an optimistic ratio.
      setSummaryReady(false);

      toast(`已标记${method}`, 'success');
      void loadWorkbenchData();
      await onRefresh({ fresh: true });
    } catch (e) {
      toast(e instanceof Error ? e.message : '操作失败', 'error');
    }
  }

  async function handleRemove(item: ActionWorkbenchItem) {
    if (!confirm('确认从清单中移除此待办记录？此操作将物理删除记录。')) return;
    try {
      await api('/api/actions/workbench', {
        method: 'POST',
        body: JSON.stringify({
          id: item.id,
          rawId: item.rawId,
          source: item.source,
          action: 'delete',
          projectId,
        }),
      });

      setItems((prev) => prev.filter((x) => x.id !== item.id));
      setTotal((prev) => Math.max(0, prev - 1));
      toast('记录已移除', 'success');
      await onRefresh();
      void loadWorkbenchData();
    } catch (e) {
      toast(e instanceof Error ? e.message : '移除失败', 'error');
    }
  }

  return (
    <div className="stack animate-fade-in">
      {/* 顶部 KPI：待办任务数 */}
      <section className="ops-metric-grid">
        <MetricCard
          theme="indigo"
          label="待办动作命中"
          value={summaryReady ? summary.totalPending : '—'}
          unit="次"
          desc="动作命中合计；同一记录可能计入多类"
          tag="待办总盘"
        />
        <MetricCard
          theme="blue"
          label="需达人回复"
          value={summaryReady ? summary.replyPending : '—'}
          unit="次"
          desc="命中回复动作的待办记录次数"
          tag="舆情承接"
        />
        <MetricCard
          theme="red"
          label="需删除违规"
          value={summaryReady ? summary.deletePending : '—'}
          unit="次"
          desc="命中删除动作的待办记录次数"
          tag="风险处置"
        />
        <MetricCard
          theme="yellow"
          label="需补充动作"
          value={summaryReady ? summary.supplementPending : '—'}
          unit="次"
          desc="命中补充动作的次数，不等于去重笔记数"
          tag="交付缺口"
        />
      </section>

      {summaryReady && !error && !loading && !needsRecalculation && <CommentEfficiencyBoard summary={summary} onSelectAction={(action) => {
        scrollAfterLoadRef.current = true;
        setLoading(true);
        setResultFocusRequest(value => value + 1);
        setActionFilter(action);
        setStatusFilter('pending');
        setSourceFilter('all');
        setQuery('');
        setDebouncedQuery('');
        setSentimentFilter('');
        setCategoryFilter('');
        setPage(1);
      }} />}

      {/* 统一处置工作台列表 */}
      <DashboardSection
        eyebrow="ACTION WORKBENCH"
        title="舆情风险与规则判定统一处置台"
        desc="整合自实时检出的关键评论与各批次审核规则判定，支持真正的服务端全量检索与分页处置。"
        extra={
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <button
              type="button"
              className="primary"
              style={{ fontSize: '13px', padding: '6px 14px' }}
              onClick={loadWorkbenchData}
              disabled={loading}
            >
              {loading ? '刷新中…' : '刷新待办'}
            </button>
            <Link
              className="btn-link"
              style={{ fontSize: '13px' }}
              href={'/api/export?type=comments&projectId=' + encodeURIComponent(projectId)}
            >
              导出关键评论 ↗
            </Link>
          </div>
        }
      >
        <WorkspaceToolbar>
          <input
            type="text"
            placeholder="搜索评论内容 / 博主 / 笔记ID / 原因"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setPage(1);
            }}
            style={{ width: '240px' }}
          />
          <select
            value={sourceFilter}
            onChange={(e) => {
              setSourceFilter(e.target.value as 'all' | 'key-comment' | 'review-batch');
              setPage(1);
            }}
          >
            <option value="all">全部来源（关键评论 + 判定批次）</option>
            <option value="key-comment">仅关键评论</option>
            <option value="review-batch">仅规则判定批次</option>
          </select>
          <select
            value={statusFilter}
            onChange={(e) => {
              setStatusFilter(e.target.value);
              setPage(1);
            }}
          >
            <option value="pending">待处理任务</option>
            <option value="handled">已处理归档</option>
            <option value="all">全部处理状态</option>
          </select>
          <select
            value={actionFilter}
            onChange={(e) => {
              setActionFilter(e.target.value);
              setPage(1);
            }}
          >
            <option value="">全部动作类型</option>
            <option value="reply">需回复</option>
            <option value="delete">需删除</option>
            <option value="supplement">需补充</option>
            <option value="observe">保留观察</option>
          </select>
          <select
            value={sentimentFilter}
            onChange={(e) => {
              setSentimentFilter(e.target.value);
              setPage(1);
            }}
          >
            <option value="">全部情绪</option>
            <option value="正向">正向</option>
            <option value="负向">负向</option>
            <option value="中立">中立</option>
            <option value="问询">问询</option>
          </select>
          <select
            value={categoryFilter}
            onChange={(e) => {
              setCategoryFilter(e.target.value);
              setPage(1);
            }}
          >
            <option value="">全部分类</option>
            <option value="产品体验">产品体验</option>
            <option value="服务物流">服务物流</option>
            <option value="导流违规">导流违规</option>
            <option value="竞品提及">竞品提及</option>
            <option value="常规互动">常规互动</option>
          </select>
          {availableDates.length > 0 && (
            <select
              value={selectedDate}
              onChange={(e) => {
                setSelectedDate(e.target.value);
                setPage(1);
              }}
              style={{ borderColor: '#c7d2fe' }}
            >
              <option value="">全部判定日期</option>
              {availableDates.map((d) => (
                <option key={d} value={d}>
                  批次：{d}
                </option>
              ))}
            </select>
          )}
        </WorkspaceToolbar>

        {needsRecalculation && (
          <div style={{ marginBottom: '14px', padding: '12px 16px', background: '#fef3c7', border: '1px solid #fde68a', borderRadius: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ color: '#92400e', fontSize: '13px', fontWeight: 600 }}>该日期尚未生成规则判定</span>
            <button
              type="button"
              className="primary"
              disabled={recalculating}
              onClick={handleRecalculate}
              style={{ fontSize: '12.5px', padding: '4px 12px' }}
            >
              {recalculating ? '正在生成判定…' : '生成本批次判定'}
            </button>
          </div>
        )}

        {error && (
          <div style={{ marginBottom: '14px' }}>
            <ResultNotice type="error">
              待办任务加载失败：{error}
              <button
                type="button"
                onClick={loadWorkbenchData}
                style={{ marginLeft: '12px', fontSize: '12px', padding: '2px 8px', cursor: 'pointer' }}
              >
                重新加载
              </button>
            </ResultNotice>
          </div>
        )}

        <div ref={resultsRef} tabIndex={-1} role="region" aria-label="待办筛选结果" style={{ scrollMarginTop: 24 }}>
        <DataTableShell
          page={page}
          pageSize={20}
          total={total}
          onPageChange={(p) => setPage(p)}
          loading={loading}
        >
          <table className="ops-table">
            <thead>
              <tr>
                <th>来源 / 动作</th>
                <th>情绪 / 分类</th>
                <th>待处置内容 / 判定样本</th>
                <th>判定原因 / 规则</th>
                <th>博主 / 笔记链接</th>
                <th>状态</th>
                <th>操作按钮</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item) => (
                <tr key={item.id}>
                  <td>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                      <StatusBadge
                        status={item.source === 'key-comment' ? '关键评论' : `判定批次 ${item.batchDate || ''}`}
                        theme={item.source === 'key-comment' ? 'blue' : 'purple'}
                      />
                      <strong
                        style={{
                          fontSize: '13px',
                          color:
                            item.action === 'delete'
                              ? '#b91c1c'
                              : item.action === 'reply'
                              ? '#0369a1'
                              : item.action === 'supplement'
                              ? '#d97706'
                              : '#334155',
                        }}
                      >
                        {item.action === 'reply'
                          ? '需回复'
                          : item.action === 'delete'
                          ? '需删除'
                          : item.action === 'supplement'
                          ? '需补充'
                          : '保留观察'}
                      </strong>
                    </div>
                  </td>
                  <td>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                      {item.sentiment && <StatusBadge status={item.sentiment} />}
                      <span style={{ fontSize: '12px', color: '#64748b' }}>{item.category || '规则判定'}</span>
                    </div>
                  </td>
                  <td style={{ maxWidth: '320px' }}>
                    <p style={{ margin: 0, fontSize: '13px', lineHeight: 1.5, color: '#0f172a' }}>
                      {item.content}
                    </p>
                  </td>
                  <td>
                    <span style={{ fontSize: '12.5px', color: '#475569' }}>{item.reason}</span>
                  </td>
                  <td>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                      <span style={{ fontSize: '13px', fontWeight: 600 }}>{item.author || '未知作者'}</span>
                      {item.link ? (
                        <a
                          href={item.link}
                          target="_blank"
                          rel="noreferrer"
                          className="text-link"
                          style={{ fontSize: '12px' }}
                        >
                          查看笔记 ↗
                        </a>
                      ) : (
                        item.noteId && (
                          openNote ? (
                            <button
                              type="button"
                              className="text-link"
                              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0, fontSize: '12px', textAlign: 'left' }}
                              onClick={() => openNote(item.noteId!)}
                            >
                              笔记明细 ({item.noteId.slice(0, 8)}…) →
                            </button>
                          ) : (
                            <small style={{ color: '#94a3b8' }}>{item.noteId.slice(0, 10)}…</small>
                          )
                        )
                      )}
                      {item.noteId && openNote && item.link && (
                        <button
                          type="button"
                          className="text-link"
                          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0, fontSize: '12px', color: '#0284c7', textAlign: 'left' }}
                          onClick={() => openNote(item.noteId!)}
                        >
                          笔记明细 →
                        </button>
                      )}
                    </div>
                  </td>
                  <td>
                    <StatusBadge
                      status={item.status === 'handled' ? '已处理' : '待处理'}
                      theme={item.status === 'handled' ? 'green' : 'yellow'}
                    />
                  </td>
                  <td>
                    <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
                      {item.status !== 'handled' ? (
                        <>
                          {item.action === 'reply' && (
                            <button
                              type="button"
                              className="primary"
                              style={{ fontSize: '12px', padding: '4px 10px', background: '#0284c7' }}
                              onClick={() => handleResolve(item, '已回复')}
                            >
                              标记已回复
                            </button>
                          )}
                          {item.action === 'delete' && (
                            <button
                              type="button"
                              className="primary"
                              style={{ fontSize: '12px', padding: '4px 10px', background: '#dc2626', borderColor: '#b91c1c' }}
                              onClick={() => handleResolve(item, '已删除')}
                            >
                              标记已删除
                            </button>
                          )}
                          {item.action === 'supplement' && (
                            <button
                              type="button"
                              className="primary"
                              style={{ fontSize: '12px', padding: '4px 10px', background: '#d97706', borderColor: '#b45309' }}
                              onClick={() => handleResolve(item, '已补充')}
                            >
                              标记已补充
                            </button>
                          )}
                          {item.action === 'observe' && (
                            <button
                              type="button"
                              className="primary"
                              style={{ fontSize: '12px', padding: '4px 10px', background: '#475569' }}
                              onClick={() => handleResolve(item, '已确认观察')}
                            >
                              标记已处理
                            </button>
                          )}
                        </>
                      ) : (
                        <span style={{ fontSize: '12px', color: '#166534', fontWeight: 600 }}>✓ 已闭环</span>
                      )}

                      {item.source === 'key-comment' && (
                        <button
                          type="button"
                          className="danger-link"
                          style={{ fontSize: '12px', padding: 0 }}
                          onClick={() => handleRemove(item)}
                        >
                          移除
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
              {!items.length && !loading && (
                <tr>
                  <td colSpan={7}>
                    <EmptyState title="暂无待办任务" text="当前筛选条件下没有待处置的评论或规则判定。" />
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </DataTableShell>
        </div>
      </DashboardSection>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from '../../components/ui/AppLink';
import { MetricCard } from '../../components/ui/operations/MetricCard';
import { DashboardSection } from '../../components/ui/operations/DashboardSection';
import { StatusBadge } from '../../components/ui/operations/StatusBadge';
import { ResultNotice } from '../../components/ui/operations/ResultNotice';
import { WorkspaceToolbar } from '../../components/ui/operations/WorkspaceToolbar';
import { DataTableShell } from '../../components/ui/operations/DataTableShell';
import { EmptyState } from '../../components/ui/EmptyState';
import { CustomSelect } from '../../components/ui/CustomSelect';
import { api, cnTime } from '../../lib/hooks/use-project-data';
import { emptyNotesSummary, type NoteListItem, type NotesListResponse } from '../content/content-view-model';
import { NoteSummaryBoard } from '../content/NoteSummaryBoard';
import { CollectionSnapshotBoard } from './CollectionSnapshotBoard';

export function CommentCollection({
  projectId,
  openNote,
  onRefresh,
  toast,
}: {
  projectId: string;
  openNote: (id: string) => void;
  onRefresh: (opts?: { fresh?: boolean }) => Promise<void>;
  toast: (msg: string, type?: 'success' | 'error' | 'info') => void;
}) {
  const searchParams = useSearchParams();
  const prefilledNoteId = searchParams.get('noteId') || '';

  const [inputDraft, setInputDraft] = useState({ source: prefilledNoteId, value: prefilledNoteId });
  const noteInput = inputDraft.source === prefilledNoteId ? inputDraft.value : prefilledNoteId;
  const setNoteInput = (value: string) => setInputDraft({ source: prefilledNoteId, value });
  const [items, setItems] = useState<NoteListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [summary, setSummary] = useState<NotesListResponse['summary']>(emptyNotesSummary);

  const [query, setQuery] = useState(searchParams.get('query') || '');
  const [monitored, setMonitored] = useState(searchParams.get('monitored') || '');
  const [page, setPage] = useState(Math.max(1, parseInt(searchParams.get('page') || '1', 10)));
  const [loading, setLoading] = useState(true);
  const [boardError, setBoardError] = useState('');
  const requestSequence = useRef(0);
  const [fetching, setFetching] = useState(false);
  const [fetchResult, setFetchResult] = useState<{ text: string; type: 'success' | 'error' } | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [debouncedQuery, setDebouncedQuery] = useState(query);
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), 300);
    return () => clearTimeout(timer);
  }, [query]);

  const syncToUrl = useCallback((nextState: { query: string; monitored: string; page: number; noteId: string }) => {
    try {
      const p = new URLSearchParams(window.location.search);
      if (nextState.query) p.set('query', nextState.query); else p.delete('query');
      if (nextState.monitored) p.set('monitored', nextState.monitored); else p.delete('monitored');
      if (nextState.page > 1) p.set('page', String(nextState.page)); else p.delete('page');
      if (nextState.noteId) p.set('noteId', nextState.noteId); else p.delete('noteId');
      window.history.replaceState(null, '', window.location.pathname + (p.toString() ? '?' + p.toString() : ''));
    } catch {}
  }, []);

  useEffect(() => {
    syncToUrl({ query: debouncedQuery, monitored, page, noteId: prefilledNoteId });
  }, [debouncedQuery, monitored, page, prefilledNoteId, syncToUrl]);

  useEffect(() => {
    const handlePopState = () => {
      const p = new URLSearchParams(window.location.search);
      setQuery(p.get('query') || '');
      setDebouncedQuery(p.get('query') || '');
      setMonitored(p.get('monitored') || '');
      setPage(Math.max(1, parseInt(p.get('page') || '1', 10)));
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const loadData = useCallback(async () => {
    const sequence = ++requestSequence.current;
    setLoading(true);
    setBoardError('');
    try {
      const p = new URLSearchParams({
        projectId,
        view: 'collection',
        page: String(page),
        pageSize: '20',
      });
      if (debouncedQuery) p.set('query', debouncedQuery);
      if (monitored) p.set('monitored', monitored);
      const res = await api<NotesListResponse>('/api/notes/list?' + p.toString());
      if (sequence !== requestSequence.current) return;
      setItems(res.items || []);
      setSelectedIds(prev => prev.filter(id => (res.items || []).some(item => item.id === id)));
      setTotal(res.total || 0);
      if (res.summary) setSummary(res.summary);
    } catch (e) {
      if (sequence !== requestSequence.current) return;
      setBoardError(e instanceof Error ? e.message : '加载失败');
      toast(e instanceof Error ? e.message : '加载采集监测列表失败', 'error');
    } finally {
      if (sequence === requestSequence.current) setLoading(false);
    }
  }, [projectId, page, debouncedQuery, monitored, toast]);

  useEffect(() => {
    const timer = setTimeout(() => {
      void loadData();
    }, 0);
    return () => { clearTimeout(timer); requestSequence.current += 1; };
  }, [loadData]);

  async function executeFetch(ids: string[]) {
    if (!ids.length) return;
    if (ids.length > 20) {
      toast('批量抓取单次最多支持 20 篇笔记，请精简后再提交', 'error');
      return;
    }
    setFetching(true);
    setFetchResult(null);
    try {
      const res = await api<{
        ok: boolean;
        results: Array<{ ok: boolean; noteId: string; fetchedL1?: number; fetchedL2?: number; total?: number; status?: string; error?: string }>;
      }>('/api/comments/fetch', {
        method: 'POST',
        body: JSON.stringify({ noteIds: ids, projectId }),
      });

      const succeeded = (res.results || []).filter((r) => r.ok).length;
      const failed = (res.results || []).length - succeeded;
      const details = (res.results || [])
        .map((r) => r.ok ? `[成功] ${r.noteId}：主评 ${r.fetchedL1}，楼中楼 ${r.fetchedL2}，总量 ${r.total}` : `[失败] ${r.noteId}：${r.error}`)
        .join('\n');

      setFetchResult({
        type: failed === 0 ? 'success' : 'error',
        text: `本次抓取完成：成功 ${succeeded} 篇，失败 ${failed} 篇。\n${details}`,
      });
      toast(`评论抓取完成 (成功 ${succeeded} / 失败 ${failed})`, succeeded > 0 ? 'success' : 'error');
      setSelectedIds([]);
      await loadData();
      await onRefresh({ fresh: true });
    } catch (e) {
      const msg = e instanceof Error ? e.message : '抓取失败';
      setFetchResult({ type: 'error', text: msg });
      toast(msg, 'error');
    } finally {
      setFetching(false);
    }
  }

  function toggleSelect(id: string) {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  }

  const isAllCurrentPageSelected = items.length > 0 && items.every((it) => selectedIds.includes(it.id));

  function selectAllOnPage() {
    if (isAllCurrentPageSelected) {
      setSelectedIds([]);
    } else {
      setSelectedIds(items.map((it) => it.id));
    }
  }

  return (
    <div className="stack animate-fade-in">
      {/* 顶部 KPI */}
      <section className="ops-metric-grid">
        <MetricCard
          theme="teal"
          label="已抓取笔记"
          value={summary.fetchedCount.toLocaleString()}
          unit="篇"
          desc="已建立评论快照，持续追踪主楼增量"
          tag="已建档快照"
        />
        <MetricCard
          theme={summary.unfetchedCount > 0 ? 'yellow' : 'green'}
          label="未抓取笔记"
          value={summary.unfetchedCount.toLocaleString()}
          unit="篇"
          desc="入库后尚未执行首轮评论采集"
          tag="待采集"
        />
        <MetricCard
          theme="blue"
          label="当前评论总量"
          value={summary.totalComments.toLocaleString()}
          unit="条"
          desc="快照累计抓取主评与楼中楼总和"
          tag="评论总盘"
        />
        <MetricCard
          theme="purple"
          label="监测资产覆盖率"
          value={summary.total ? `${Math.round((summary.fetchedCount / summary.total) * 1000) / 10}%` : '—'}
          desc={`总资产 ${summary.total} 篇 · 已纳管采集`}
          tag="覆盖比例"
        />
      </section>

      <div className="workspace-two-col">
        <NoteSummaryBoard mode="collection" summary={summary} loading={loading} error={boardError} />
        <CollectionSnapshotBoard items={items} loading={loading} error={boardError} />
      </div>

      {/* 醒目的青色采集操作卡 */}
      <DashboardSection
        eyebrow="COMMENT INGESTION"
        title="手动采集与增量比对"
        desc="输入小红书笔记 ID 或链接，每行一个；系统将按规则抓取全量主评论与楼中楼，自动增量比对并计算验收状态。"
      >
        <div className="ops-action-card ops-action-card-teal" style={{ padding: '20px' }}>
          <label style={{ fontSize: '13px', fontWeight: 600, color: '#0f172a', marginBottom: '6px', display: 'block' }}>
            小红书笔记 ID 或完整链接（支持粘贴多行，单次上限 20 篇）
          </label>
          <textarea
            rows={3}
            placeholder={'粘贴小红书笔记链接或 24 位十六进制 ID，例如：\n6a01be210000000035033cb8\nhttps://www.xiaohongshu.com/explore/6a01be210000000035033cb8'}
            value={noteInput}
            onChange={(e) => setNoteInput(e.target.value)}
            style={{
              width: '100%',
              padding: '10px 12px',
              borderRadius: '8px',
              border: '1px solid #99f6e4',
              background: '#ffffff',
              fontSize: '13px',
              fontFamily: 'monospace',
              outline: 'none',
            }}
          />
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '10px', flexWrap: 'wrap', gap: '10px' }}>
            <span style={{ fontSize: '12px', color: '#0f766e' }}>
              💡 提示：从内容台账点击“前往评论监测”可自动预填 ID。确认后点击开始抓取。
            </span>
            <button
              type="button"
              className="primary"
              disabled={fetching || !noteInput.trim()}
              onClick={() => {
                const lines = noteInput.split(/[\n,，]+/).map((s) => s.trim()).filter(Boolean);
                if (lines.length > 20) {
                  toast('单次最多提交 20 篇笔记，请精简行数后再提交', 'error');
                  return;
                }
                executeFetch(lines);
              }}
              style={{ background: '#0d9488', borderColor: '#0f766e', minWidth: '130px' }}
            >
              {fetching ? '正在采集比对…' : '开始抓取评论'}
            </button>
          </div>
          {fetchResult && (
            <ResultNotice type={fetchResult.type} className="mt-2">
              {fetchResult.text}
            </ResultNotice>
          )}
        </div>
      </DashboardSection>

      {/* 采集监测列表 */}
      <DashboardSection
        eyebrow="MONITORING LIST"
        title="评论快照与监测明细"
        desc="监控所有笔记的评论总量、增量变化与验收状态，支持单篇重新采集与批量顺序抓取。"
        extra={
          <Link href={`/projects/${encodeURIComponent(projectId)}/comments?tab=acceptance`} className="btn-link" style={{ fontSize: '13px' }}>
            前往交付验收 →
          </Link>
        }
      >
        <WorkspaceToolbar
          extra={
            selectedIds.length > 0 && (
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', background: '#e0f2fe', padding: '4px 12px', borderRadius: '8px' }}>
                <span style={{ fontSize: '12.5px', color: '#0369a1', fontWeight: 600 }}>
                  已勾选 {selectedIds.length} 篇
                </span>
                <button
                  type="button"
                  className="primary"
                  style={{ fontSize: '12px', padding: '4px 10px' }}
                  disabled={fetching}
                  onClick={() => executeFetch(selectedIds)}
                >
                  {fetching ? '抓取中…' : '批量重新抓取'}
                </button>
                <button
                  type="button"
                  style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '12px', color: '#64748b' }}
                  onClick={() => setSelectedIds([])}
                >
                  取消
                </button>
              </div>
            )
          }
        >
          <input
            type="text"
            placeholder="搜索笔记 / 博主 / ID"
            value={query}
            onChange={(e) => { setQuery(e.target.value); setPage(1); }}
            style={{ width: '220px' }}
          />
          <CustomSelect
            value={monitored}
            onChange={(val) => { setMonitored(val); setPage(1); }}
            options={[
              { value: '', label: '全部监测状态' },
              { value: '1', label: '已抓取快照' },
              { value: '0', label: '未抓取' },
            ]}
            style={{ minWidth: 140 }}
          />
        </WorkspaceToolbar>

        <DataTableShell
          page={page}
          pageSize={20}
          total={total}
          onPageChange={(p) => setPage(p)}
          loading={loading}
        >
          <table className="ops-table">
            <thead>
              <tr>
                <th style={{ width: '36px' }}>
                  <input
                    type="checkbox"
                    checked={isAllCurrentPageSelected}
                    onChange={selectAllOnPage}
                  />
                </th>
                <th>笔记信息</th>
                <th>来源</th>
                <th>最近抓取时间</th>
                <th>主评论</th>
                <th>楼中楼</th>
                <th>评论总数</th>
                <th>较上次变化</th>
                <th>验收状态</th>
                <th>操作</th>
              </tr>
            </thead>
            <tbody>
              {items.map((note) => {
                const isSelected = selectedIds.includes(note.id);
                return (
                  <tr key={note.id} style={{ background: isSelected ? '#f0f9ff' : undefined }}>
                    <td>
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelect(note.id)}
                      />
                    </td>
                    <td>
                      <div className="ops-table-note-cell">
                        {note.coverUrl ? (
                          <img
                            src={note.coverUrl}
                            alt=""
                            className="ops-table-note-cover"
                            loading="lazy"
                            decoding="async"
                            referrerPolicy="no-referrer"
                            onError={(e) => {
                              if (!e.currentTarget.dataset.retried) {
                                e.currentTarget.dataset.retried = '1';
                                e.currentTarget.src = '/api/note-covers?projectId=' + encodeURIComponent(projectId) + '&noteId=' + encodeURIComponent(note.id);
                              } else {
                                e.currentTarget.onerror = null;
                                e.currentTarget.src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="%2394a3b8" stroke-width="1.5"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="m3 15 5-5c.9-.9 2.1-.9 3 0l7 7"/><circle cx="8.5" cy="8.5" r="1.5"/></svg>';
                              }
                            }}
                          />
                        ) : (
                          <div className="ops-table-note-cover">
                            {(note.author || '笔').slice(0, 1)}
                          </div>
                        )}
                        <div className="ops-table-note-info">
                          <span
                            className="ops-table-note-title"
                            title={note.title || note.id}
                            style={{ cursor: 'pointer', color: '#0284c7' }}
                            onClick={() => openNote(note.id)}
                          >
                            {note.title || '未命名笔记'}
                          </span>
                          <span className="ops-table-note-sub">
                            {note.author || '未知博主'} · <small style={{ fontFamily: 'monospace' }}>{note.id.slice(0, 10)}…</small>
                          </span>
                        </div>
                      </div>
                    </td>
                    <td>
                      <StatusBadge status={note.sourceType === 'owned' ? '自有发布' : note.sourceType === 'commercial' ? '商业合作' : '外部扫描'} />
                    </td>
                    <td>
                      <span style={{ fontSize: '12.5px', color: '#475569' }}>
                        {note.lastFetchedAt ? cnTime(note.lastFetchedAt) : '尚未抓取'}
                      </span>
                    </td>
                    <td>
                      <strong>{note.latestL1Count ?? (note.isFetched ? '—' : '0')}</strong>
                    </td>
                    <td>
                      <strong>{note.latestL2Count ?? (note.isFetched ? '—' : '0')}</strong>
                    </td>
                    <td>
                      <strong>{note.commentTotal}</strong>
                    </td>
                    <td>
                      {note.commentDelta == null ? (
                        <span style={{ color: '#94a3b8' }}>{note.latestSnapshotTotal != null ? '首次采集' : '—'}</span>
                      ) : note.commentDelta > 0 ? (
                        <span style={{ color: '#15803d', fontWeight: 600 }}>+{note.commentDelta}</span>
                      ) : note.commentDelta < 0 ? (
                        <span style={{ color: '#b91c1c', fontWeight: 600 }}>{note.commentDelta}</span>
                      ) : (
                        <span style={{ color: '#64748b' }}>持平</span>
                      )}
                    </td>
                    <td>
                      <StatusBadge status={note.status || '待抓取'} />
                    </td>
                    <td>
                      <div style={{ display: 'flex', gap: '8px', alignItems: 'center', whiteSpace: 'nowrap' }}>
                        <button
                          type="button"
                          className="text-link"
                          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
                          onClick={() => openNote(note.id)}
                        >
                          评论详情
                        </button>
                        <button
                          type="button"
                          className="text-link"
                          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0, color: '#0d9488' }}
                          disabled={fetching}
                          onClick={() => executeFetch([note.id])}
                        >
                          重新采集
                        </button>
                        {note.url && (
                          <a
                            href={note.url}
                            target="_blank"
                            rel="noreferrer"
                            className="text-link"
                            style={{ color: '#64748b' }}
                          >
                            原笔记 ↗
                          </a>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {!items.length && !loading && (
                <tr>
                  <td colSpan={10}>
                    <EmptyState title="未找到监测笔记" text="输入笔记链接开始采集，或在内容管理中导入自有笔记。" />
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </DataTableShell>
      </DashboardSection>
    </div>
  );
}

'use client';
import { loadXLSX } from '../../lib/xlsx-loader';

import { useState } from 'react';
import type { Dashboard, Ops } from '../../lib/types/project';
import { FeishuSources, SyncButton } from '../../components/ui/FeishuSources';
import { PageHeader } from '../../components/ui/PageHeader';
import { WorkspaceModuleTabs, type ModuleTab } from '../../components/ui/operations/WorkspaceModuleTabs';
import { VoiceIntelligence } from './VoiceIntelligence';
import { CommentCollection } from './CommentCollection';
import { CommentActionWorkbench } from './CommentActionWorkbench';
import { AcceptanceDelivery } from './AcceptanceDelivery';
import { SupplierVerification } from './SupplierVerification';
import { ExecutionOverview } from './ExecutionOverview';
import { useProjectTab } from '../../lib/hooks/useProjectTab';
import { useNoteDetail } from '../../lib/hooks/useNoteDetail';
import { useCategoryNotesModal } from '../../components/notes-modal/CategoryNotesModal';
import { useProject } from '../../components/project-shell/ProjectContext';
import { api, num, pct } from '../../lib/hooks/use-project-data';

export function CommentsWorkspace({
  projectId,
  dashboard,
  ops,
  onRefresh,
}: {
  projectId: string;
  dashboard: Dashboard;
  ops: Ops;
  onRefresh: (opts?: { fresh?: boolean }) => Promise<void>;
}) {
  const [tab, setTab] = useProjectTab('actions', ['actions', 'collection', 'acceptance', 'supplier', 'execution'], {
    insights: 'actions',
    sentiment: 'actions',
    voice: 'actions',
    risk: 'actions',
    review: 'actions',
  });
  const [subView, setSubView] = useState<'voice' | 'triage'>(() => {
    if (typeof window !== 'undefined') {
      const p = new URLSearchParams(window.location.search);
      const t = p.get('tab');
      if (t === 'actions' || t === 'risk' || t === 'review') return 'triage';
    }
    return 'voice';
  });
  const { showToast } = useProject();

  const { openNote, renderDrawer } = useNoteDetail({
    projectId,
    onRefresh,
    toast: showToast,
    context: tab === 'acceptance' ? 'acceptance' : 'comments',
    defaultTab: tab === 'acceptance' ? 'acceptance' : 'comments',
  });

  const { openCategoryNotes, renderCategoryNotesModal } = useCategoryNotesModal({
    projectId,
  });

  const [loading, setLoading] = useState(false);
  const [runResult, setRunResult] = useState('');

  const supplier = dashboard.metrics.supplier || {};
  const actions = dashboard.metrics.actions || {};
  const pendingRisk = num(actions.replyPending) + num(actions.deletePending);
  const verifiedCount = num(supplier.exactCount) + num(supplier.modifiedCount);
  const totalActions = num(actions.total) || 0;

  async function uploadWorkbook(file: File | undefined, kind: 'owned' | 'supplier') {
    if (!file) return;
    setLoading(true);
    setRunResult('');
    try {
      const XLSX = await loadXLSX();
      const book = XLSX.read(await file.arrayBuffer());
      const rows = XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]], { defval: '' });
      const result = await api<{ imported: number; skipped: number }>('/api/import', {
        method: 'POST',
        body: JSON.stringify({ kind, rows, projectId }),
      });
      showToast('表格导入完成，导入 ' + result.imported + ' 条，跳过 ' + result.skipped + ' 条', 'success');
      setRunResult('导入 ' + result.imported + ' 条，跳过 ' + result.skipped + ' 条。');
      await onRefresh({ fresh: true });
    } catch (err) {
      showToast(err instanceof Error ? err.message : '导入失败', 'error');
    } finally {
      setLoading(false);
    }
  }

  async function verifySupplier() {
    setLoading(true);
    setRunResult('正在初始化供应商评论核验…');
    try {
      let totalExact = 0;
      let totalModified = 0;
      let totalMissing = 0;
      let totalFailedNotes = 0;
      let totalProcessed = 0;
      let remaining = 1;
      let round = 0;

      while (remaining > 0) {
        round++;
        const result = await api<{
          summary: { exact: number; modified: number; missing: number; failedNotes: number };
          processed?: number;
          remaining?: number;
          failedNotes?: number;
        }>('/api/supplier/verify', {
          method: 'POST',
          body: JSON.stringify({ projectId }),
        });
        const processed = result.processed ?? (result.summary.exact + result.summary.modified + result.summary.missing);
        totalProcessed += processed;
        totalExact += result.summary.exact;
        totalModified += result.summary.modified;
        totalMissing += result.summary.missing;
        totalFailedNotes += (result.failedNotes ?? 0);
        remaining = result.remaining ?? 0;

        if (processed === 0) break;

        setRunResult(
          `外显核验进行中（第 ${round} 轮）：已处理 ${totalProcessed} 条${remaining > 0 ? `，剩余待核验 ${remaining} 条…` : '，全部完成'}`
        );
      }

      showToast(`供应商评论核验完成，累计处理 ${totalProcessed} 条`, 'success');
      setRunResult(
        `外显核验完成：原文一致 ${totalExact}，有修改 ${totalModified}，未外显 ${totalMissing}。共处理 ${totalProcessed} 条。`
      );
      await onRefresh({ fresh: true });
    } catch (err) {
      showToast(err instanceof Error ? err.message : '核验失败', 'error');
    } finally {
      setLoading(false);
    }
  }

  const tabs: ModuleTab[] = [
    { id: 'actions', title: '口碑与处置', desc: '情绪构成、动态话题与规则闭环', badge: `${pct(dashboard.metrics.positiveRate)} · ${pendingRisk}待办`, icon: '💬' },
    { id: 'collection', title: '采集监测', desc: '按ID/链接抓取、批量采集与快照变动', badge: dashboard.metrics.commentTotal || 0, icon: '🛰️' },
    { id: 'acceptance', title: '交付验收', desc: '主线交付、可汇报线与品牌提及率', badge: dashboard.metrics.noteCount || 0, icon: '🎯' },
    { id: 'supplier', title: '供应商核验', desc: '交付Excel导入、隔天外显与共性分析', badge: verifiedCount || 0, icon: '🛡️' },
    { id: 'execution', title: '执行总览', desc: '执行量、闭环进度、质量监控与任务管线', badge: totalActions || 0, icon: '📊' },
  ];

  return (
    <div className="ops-workspace overview-colorful-page reference-workspace" data-workspace-ui="v2">
      <PageHeader
        variant="light"
        eyebrow="FEIHE · Q3 COMMENTS"
        title="评论运营"
        subtitle="2026年 Q3 · 小红书口碑分析、评论采集、风险处置与供应商核验"
        badge={
          <span>
            {verifiedCount} 已确认外显 · {pendingRisk} 风险待办
          </span>
        }
      >
        <div className="workspace-header-actions">
          <SyncButton projectId={projectId} onRefresh={onRefresh} />
        </div>
      </PageHeader>

      <WorkspaceModuleTabs tabs={tabs} activeTab={tab} onChange={setTab} variant="compact" />
      <FeishuSources data={dashboard.feishu} projectId={projectId} />

      <div
        id={`workspace-tabpanel-${tab}`}
        role="tabpanel"
        aria-labelledby={`workspace-tab-${tab}`}
        tabIndex={0}
        className="overview-block-content"
      >
      {tab === 'collection' && (
        <CommentCollection
          projectId={projectId}
          openNote={openNote}
          onRefresh={onRefresh}
          toast={showToast}
        />
      )}

      {tab === 'actions' && (
        <div className="stack animate-fade-in">
          <div className="reference-subtabs" aria-label="口碑与处置视图">
            <button type="button" aria-pressed={subView === 'voice'} onClick={() => setSubView('voice')}>口碑大盘</button>
            <button type="button" aria-pressed={subView === 'triage'} onClick={() => setSubView('triage')}>待办处置清单 ({pendingRisk})</button>
          </div>

           {subView === 'voice' ? (
             <VoiceIntelligence
               data={dashboard}
               onSwitchTab={() => setSubView('triage')}
             />
           ) : (
             <CommentActionWorkbench
               projectId={projectId}
               openNote={openNote}
               onRefresh={onRefresh}
               toast={showToast}
             />
           )}
         </div>
       )}

       {tab === 'acceptance' && (
         <AcceptanceDelivery
           projectId={projectId}
           dashboard={dashboard}
           openCategoryNotes={openCategoryNotes}
           acceptance={ops.settings.acceptance}
           openNote={openNote}
           toast={showToast}
         />
       )}

       {tab === 'supplier' && (
         <SupplierVerification
           projectId={projectId}
           ops={ops}
           openNote={openNote}
           uploadWorkbook={uploadWorkbook}
           verifySupplier={verifySupplier}
           loading={loading}
          runResult={runResult}
          onDone={onRefresh}
          toast={showToast}
        />
      )}

      {tab === 'execution' && (
        <ExecutionOverview dashboard={dashboard} ops={ops} openCategoryNotes={openCategoryNotes} />
      )}
      </div>

      {renderDrawer()}
      {renderCategoryNotesModal()}
    </div>
  );
}

'use client';
import { useEffect, useState } from 'react';
import { api } from '../../lib/hooks/use-project-data';
import { PanelHead } from '../../components/ui/PanelHead';
import { EmptyState } from '../../components/ui/EmptyState';
type QueueItem = { id: number; link: string; blogger: string; action: string; reason: string; sample: string[]; status: string };
const GROUPS: Array<{ key: string; title: string; desc: string }> = [
  { key: 'needReply', title: '需达人回复', desc: '用户问询无人接，达人24小时内回' },
  { key: 'needDelete', title: '需删除', desc: '负面/导流/不相关，按口径删' },
  { key: 'needSupplement', title: '需补充', desc: '正向不足30条，算缺口补量' },
];
export function ReviewActionQueue({ projectId }: { projectId: string }) {
  const [dates, setDates] = useState<string[]>([]);
  const [date, setDate] = useState('08-30');
  const [counts, setCounts] = useState<Record<string, number>>({});
  const [items, setItems] = useState<QueueItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [note, setNote] = useState('');
  async function load(d: string) {
    setLoading(true);
    setNote('');
    try {
      const r = await api<{ ok: boolean; counts: Record<string, number>; items: QueueItem[] }>(
        '/api/review?projectId=' + encodeURIComponent(projectId) + '&date=' + encodeURIComponent(d) + '&items=1'
      );
      setCounts(r.counts || {});
      setItems(r.items || []);
      if (!(r.items || []).length) setNote(d + ' 暂无处置事项，说明当日判定全员达标。');
    } catch (e) {
      setItems([]);
      setNote(e instanceof Error ? e.message : '加载失败');
    } finally {
      setLoading(false);
    }
  }
  useEffect(() => {
    api<{ ok: boolean; dates: string[] }>('/api/review?projectId=' + encodeURIComponent(projectId))
      .then((r) => {
        const ds = r.dates || [];
        setDates(ds);
        const pick = ds.includes('08-30') ? '08-30' : ds[ds.length - 1] || '08-30';
        setDate(pick);
        load(pick);
      })
      .catch(() => load('08-30'));
  }, [projectId]);
  async function resolve(id: number) {
    try {
      await api('/api/review', { method: 'POST', body: JSON.stringify({ projectId, action: 'resolve', id }) });
      setItems((list) => list.map((it) => (it.id === id ? { ...it, status: '已处理' } : it)));
    } catch (e) {
      setNote(e instanceof Error ? e.message : '更新失败');
    }
  }
  return (
    <section className="panel" id="review-queue">
      <PanelHead eyebrow="REVIEW QUEUE" title="判定处置队列" />
      <div className="filterbar">
        <select value={date} onChange={(e) => { setDate(e.target.value); load(e.target.value); }}>
          {[...dates].sort().reverse().map((d) => (
            <option key={d} value={d}>{d} 判定批次</option>
          ))}
        </select>
        <button onClick={() => load(date)} disabled={loading}>{loading ? '判定中…' : '重新判定'}</button>
        <span>需回复 {counts.needReply || 0} · 需删除 {counts.needDelete || 0} · 需补充 {counts.needSupplement || 0}</span>
      </div>
      {note ? <p className="muted">{note}</p> : null}
      <div className="queue-grid">
        {GROUPS.map((g) => {
          const rows = items.filter((it) => it.action === g.key);
          return (
            <article className="queue-card" key={g.key}>
              <header>
                <strong>{g.title} {rows.length}</strong>
                <small>{g.desc}</small>
              </header>
              <div className="queue-list">
                {rows.length ? (
                  rows.map((it) => (
                    <div className="queue-row" key={it.id}>
                      <div className="queue-main">
                        <div><b>{it.blogger || '未知博主'}</b><span>{it.reason}</span></div>
                        {(it.sample || []).slice(0, 1).map((s, i) => (<p key={i}>“{s.slice(0, 60)}”</p>))}
                        <small><a href={it.link} target="_blank" rel="noreferrer">打开笔记 ↗</a> · {it.status}</small>
                      </div>
                      {it.status !== '已处理' ? (
                        <button onClick={() => resolve(it.id)}>已处理</button>
                      ) : (
                        <span className="done">已处理</span>
                      )}
                    </div>
                  ))
                ) : (
                  <EmptyState title="本组无待办" text="当前日期该组判定全部通过。" />
                )}
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
}

import { NoteThumbnail } from '../../components/ui/NoteThumbnail';
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from '../../components/ui/AppLink';
import { MetricCard } from '../../components/ui/operations/MetricCard';
import { DashboardSection } from '../../components/ui/operations/DashboardSection';
import { StatusBadge } from '../../components/ui/operations/StatusBadge';
import { WorkspaceToolbar } from '../../components/ui/operations/WorkspaceToolbar';
import { DataTableShell } from '../../components/ui/operations/DataTableShell';
import { EmptyState } from '../../components/ui/EmptyState';
import { api, compact, cnTime, pct } from '../../lib/hooks/use-project-data';
import { emptyNotesSummary, type NoteListItem, type NotesListResponse } from './content-view-model';
import { NoteSummaryBoard } from './NoteSummaryBoard';

export function ContentRegistry({
  projectId,
  openNote,
  uploadWorkbook,
  runSearch,
  loading: globalLoading,
  onRefresh,
  toast,
}: {
  projectId: string;
  openNote: (id: string) => void;
  uploadWorkbook: (file: File | undefined, kind: 'owned' | 'supplier') => void;
  runSearch: (keywords: string, from: string, to: string) => Promise<void>;
  loading: boolean;
  onRefresh: () => Promise<void>;
  toast: (msg: string, type?: 'success' | 'error' | 'info') => void;
}) {
  const [items, setItems] = useState<NoteListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [summary, setSummary] = useState<NotesListResponse['summary']>(emptyNotesSummary);

  // Filter states
  const searchParams = useSearchParams();
  const [query, setQuery] = useState(searchParams.get('query') || '');
  const [source, setSource] = useState(searchParams.get('source') || '');
  const [scope, setScope] = useState(searchParams.get('scope') || '');
  const [status, setStatus] = useState(searchParams.get('status') || '');
  const [category, setCategory] = useState(searchParams.get('category') || '');
  const [from, setFrom] = useState(searchParams.get('from') || '');
  const [to, setTo] = useState(searchParams.get('to') || '');
  const [sort, setSort] = useState(searchParams.get('sort') || '');
  const [order, setOrder] = useState(searchParams.get('order') || 'desc');
  const [page, setPage] = useState(Math.max(1, parseInt(searchParams.get('page') || '1', 10)));
  const [loading, setLoading] = useState(false);
  const [boardError, setBoardError] = useState('');
  const reqSeqRef = useRef(0);
  const [activeIngestion, setActiveIngestion] = useState<'import' | 'scan' | null>(null);
  const [showMoreFilters, setShowMoreFilters] = useState(false);

  const hasAdvancedFilters = Boolean(category || from || to || sort);
  const activeFilterCount = [source, scope, status, category, from, to, query, sort].filter(Boolean).length;

  const resetFilters = () => {
    setQuery('');
    setDebouncedQuery('');
    setSource('');
    setScope('');
    setStatus('');
    setCategory('');
    setFrom('');
    setTo('');
    setSort('');
    setOrder('desc');
    setPage(1);
  };

  const [debouncedQuery, setDebouncedQuery] = useState(query);
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), 300);
    return () => clearTimeout(timer);
  }, [query]);

  const syncToUrl = useCallback((nextState: { query: string; source: string; scope: string; status: string; category: string; from: string; to: string; sort: string; order: string; page: number }) => {
    try {
      const p = new URLSearchParams(window.location.search);
      if (nextState.query) p.set('query', nextState.query); else p.delete('query');
      if (nextState.source) p.set('source', nextState.source); else p.delete('source');
      if (nextState.scope) p.set('scope', nextState.scope); else p.delete('scope');
      if (nextState.status) p.set('status', nextState.status); else p.delete('status');
      if (nextState.category) p.set('category', nextState.category); else p.delete('category');
      if (nextState.from) p.set('from', nextState.from); else p.delete('from');
      if (nextState.to) p.set('to', nextState.to); else p.delete('to');
      if (nextState.sort) p.set('sort', nextState.sort); else p.delete('sort');
      if (nextState.order && nextState.order !== 'desc') p.set('order', nextState.order); else p.delete('order');
      if (nextState.page > 1) p.set('page', String(nextState.page)); else p.delete('page');
      window.history.replaceState(null, '', window.location.pathname + (p.toString() ? '?' + p.toString() : ''));
    } catch {}
  }, []);

  useEffect(() => {
    syncToUrl({ query: debouncedQuery, source, scope, status, category, from, to, sort, order, page });
  }, [debouncedQuery, source, scope, status, category, from, to, sort, order, page, syncToUrl]);

  useEffect(() => {
    const handlePopState = () => {
      const p = new URLSearchParams(window.location.search);
      setQuery(p.get('query') || '');
      setDebouncedQuery(p.get('query') || '');
      setSource(p.get('source') || '');
      setScope(p.get('scope') || '');
      setStatus(p.get('status') || '');
      setCategory(p.get('category') || '');
      setFrom(p.get('from') || '');
      setTo(p.get('to') || '');
      setSort(p.get('sort') || '');
      setOrder(p.get('order') || 'desc');
      setPage(Math.max(1, parseInt(p.get('page') || '1', 10)));
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);
  // External sample scan inputs
  const [keywords, setKeywords] = useState('启萃,飞鹤奶粉');
  const [scanFrom, setScanFrom] = useState(() => new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10));
  const [scanTo, setScanTo] = useState(() => new Date().toISOString().slice(0, 10));
  const [scanning, setScanning] = useState(false);
  const [scanResult, setScanResult] = useState('');

  // Excel file upload input
  const [uploadFileName, setUploadFileName] = useState('');

  const loadData = useCallback(async () => {
    const seq = ++reqSeqRef.current;
    setLoading(true);
    setBoardError('');
    try {
      const p = new URLSearchParams({
        projectId,
        view: 'registry',
        page: String(page),
        pageSize: '20',
      });
      if (debouncedQuery) p.set('query', debouncedQuery);
      if (source) p.set('source', source);
      if (scope) p.set('scope', scope);
      if (status) p.set('status', status);
      if (category) p.set('category', category);
      if (from) p.set('from', from);
      if (to) p.set('to', to);
      if (sort) {
        p.set('sort', sort);
        p.set('order', order);
      }

      const res = await api<NotesListResponse>('/api/notes/list?' + p.toString());
      if (seq !== reqSeqRef.current) return;
      setItems(res.items || []);
      setTotal(res.total || 0);
      if (res.summary) setSummary(res.summary);
    } catch (e) {
      if (seq !== reqSeqRef.current) return;
      setBoardError(e instanceof Error ? e.message : '加载失败');
      toast(e instanceof Error ? e.message : '加载失败', 'error');
    } finally {
      if (seq === reqSeqRef.current) setLoading(false);
    }
  }, [projectId, page, debouncedQuery, source, scope, status, category, from, to, sort, order, toast]);

  useEffect(() => {
    let cancelled = false;
    const timer = setTimeout(() => {
      if (!cancelled) void loadData();
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [loadData]);

  async function handleScan() {
    setScanning(true);
    setScanResult('');
    try {
      await runSearch(keywords, scanFrom, scanTo);
      setScanResult('外部内容样本扫描入库已触发完成');
      await loadData();
    } catch (e) {
      setScanResult(e instanceof Error ? e.message : '扫描失败');
    } finally {
      setScanning(false);
    }
  }

  return (
    <div className="stack animate-fade-in">
      {/* 4 大真实经营 KPI */}
      <section className="ops-metric-grid">
        <MetricCard
          theme="blue"
          label="全部内容资产"
          value={summary.total.toLocaleString()}
          unit="篇"
          desc="项目库中已建档管理的完整内容台账"
          tag="资产总盘"
        />
        <MetricCard
          theme="green"
          label="自有 / 商业内容"
          value={summary.ownedCount.toLocaleString()}
          unit="篇"
          desc={summary.total ? `占总盘 ${pct(summary.ownedCount / summary.total)} · 自有投放与达人合作` : '—'}
          tag="重点运营"
        />
        <MetricCard
          theme="purple"
          label="外部扫描样本"
          value={summary.scanCount.toLocaleString()}
          unit="篇"
          desc={summary.total ? `占总盘 ${pct(summary.scanCount / summary.total)} · 关键词自然讨论池` : '—'}
          tag="自然沉淀"
        />
        <MetricCard
          theme={summary.missingBasicProfileCount > 0 ? 'yellow' : 'teal'}
          label="待补基础资料"
          value={summary.missingBasicProfileCount.toLocaleString()}
          unit="篇"
          desc={summary.total ? `基础资料完整度 ${pct(summary.basicProfileCount / summary.total)}` : '—'}
          tag="数据质量"
        />
      </section>

      {/* 按需展开的入库操作抽屉/区域 */}
      {activeIngestion === 'import' && (
        <div className="ops-action-card ops-action-card-blue animate-scale-in" style={{ marginBottom: '14px', border: '1px solid #bfdbfe' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '20px' }}>📥</span>
              <div>
                <strong style={{ fontSize: '14px', color: '#0f172a' }}>导入自有发布内容</strong>
                <div style={{ fontSize: '12px', color: '#64748b' }}>支持 .xlsx / .xls 格式，自动识别笔记 ID、达人与产品范围</div>
              </div>
            </div>
            <button type="button" onClick={() => setActiveIngestion(null)} style={{ background: 'none', border: 'none', fontSize: '16px', cursor: 'pointer', color: '#64748b' }}>✕ 收起</button>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginTop: '10px' }}>
            <label className="upload" style={{ margin: 0, cursor: 'pointer' }}>
              选择 Excel 文件
              <input
                type="file"
                accept=".xlsx,.xls"
                onChange={async (e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    setUploadFileName(file.name);
                    try {
                      await uploadWorkbook(file, 'owned');
                      await loadData();
                      await onRefresh();
                    } catch (err) {
                      toast(err instanceof Error ? err.message : '导入失败', 'error');
                    }
                  }
                }}
              />
            </label>
            {uploadFileName && (
              <span style={{ fontSize: '12px', color: '#0284c7', fontWeight: 500 }}>
                已选：{uploadFileName}
              </span>
            )}
            {globalLoading && <span style={{ fontSize: '12px', color: '#64748b' }}>上传导入中…</span>}
          </div>
        </div>
      )}

      {activeIngestion === 'scan' && (
        <div className="ops-action-card ops-action-card-purple animate-scale-in" style={{ marginBottom: '14px', border: '1px solid #ddd6fe' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '20px' }}>🔍</span>
              <div>
                <strong style={{ fontSize: '14px', color: '#0f172a' }}>关键词扫描外部样本</strong>
                <div style={{ fontSize: '12px', color: '#64748b' }}>补充自然讨论样本池</div>
              </div>
            </div>
            <button type="button" onClick={() => setActiveIngestion(null)} style={{ background: 'none', border: 'none', fontSize: '16px', cursor: 'pointer', color: '#64748b' }}>✕ 收起</button>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center', marginTop: '10px' }}>
            <input
              style={{ flex: 1, minWidth: '180px', padding: '6px 10px', border: '1px solid #cbd5e1', borderRadius: '6px', fontSize: '13px' }}
              value={keywords}
              onChange={(e) => setKeywords(e.target.value)}
              placeholder="关键词用逗号分隔"
            />
            <input
              type="date"
              style={{ padding: '5px 8px', border: '1px solid #cbd5e1', borderRadius: '6px', fontSize: '12px' }}
              value={scanFrom}
              onChange={(e) => setScanFrom(e.target.value)}
            />
            <span style={{ fontSize: '12px', color: '#64748b' }}>至</span>
            <input
              type="date"
              style={{ padding: '5px 8px', border: '1px solid #cbd5e1', borderRadius: '6px', fontSize: '12px' }}
              value={scanTo}
              onChange={(e) => setScanTo(e.target.value)}
            />
            <button
              type="button"
              className="primary"
              style={{ fontSize: '12.5px', padding: '6px 12px', background: '#6d28d9', borderColor: '#5b21b6' }}
              disabled={scanning || !keywords.trim()}
              onClick={handleScan}
            >
              {scanning ? '扫描中…' : '执行扫描'}
            </button>
          </div>
          {scanResult && <div style={{ fontSize: '12px', color: '#6d28d9', marginTop: '6px' }}>{scanResult}</div>}
        </div>
      )}

      {/* 第三部分：筛选与内容台账 */}
      <DashboardSection
        eyebrow="NOTE REGISTRY"
        title="内容资产明细台账"
        desc="集中管理单篇内容元数据与最新评论监测摘要，评论采集与运营请前往评论运营。"
        extra={
          <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
            <button
              type="button"
              className="subtle-btn"
              style={{ fontSize: '12.5px', padding: '5px 12px', background: activeIngestion === 'import' ? '#eff6ff' : '#fff', color: activeIngestion === 'import' ? '#0284c7' : '#334155', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer' }}
              onClick={() => setActiveIngestion(activeIngestion === 'import' ? null : 'import')}
            >
              📥 批量导入内容
            </button>
            <button
              type="button"
              className="subtle-btn"
              style={{ fontSize: '12.5px', padding: '5px 12px', background: activeIngestion === 'scan' ? '#f5f3ff' : '#fff', color: activeIngestion === 'scan' ? '#7c3aed' : '#334155', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer' }}
              onClick={() => setActiveIngestion(activeIngestion === 'scan' ? null : 'scan')}
            >
              🔍 扫描外部样本
            </button>
            <button
              type="button"
              className="subtle-btn"
              style={{ fontSize: '12.5px', padding: '5px 12px', background: '#ffffff', color: '#334155', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer' }}
              onClick={() => { loadData(); onRefresh(); }}
              disabled={loading}
            >
              {loading ? '刷新中…' : '刷新台账'}
            </button>
            <Link
              className="subtle-btn"
              style={{ fontSize: '12.5px', padding: '5px 12px', background: '#ffffff', color: '#334155', border: '1px solid #cbd5e1', borderRadius: '6px', textDecoration: 'none', display: 'inline-flex', alignItems: 'center' }}
              href={'/api/export?type=notes&projectId=' + encodeURIComponent(projectId)}
            >
              导出台账 ↗
            </Link>
          </div>
        }
      >
        <WorkspaceToolbar>
          <input
            type="text"
            placeholder="搜索标题 / 博主 / 笔记ID"
            value={query}
            onChange={(e) => { setQuery(e.target.value); setPage(1); }}
            style={{ width: '200px' }}
          />
          <select value={source} onChange={(e) => { setSource(e.target.value); setPage(1); }}>
            <option value="">全部来源</option>
            <option value="owned">自有发布</option>
            <option value="commercial">商业合作</option>
            <option value="keyword_scan">关键词扫描</option>
          </select>
